#!/usr/bin/env python3
from __future__ import annotations

import argparse
import dataclasses
import datetime as dt
import html
import hashlib
import ipaddress
import json
import os
import re
import shlex
import socket
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any, Callable


VERSION = "0.2.15"
DEFAULT_LITELLM_URL = os.environ.get("HERMCLAW_LITELLM_URL", "http://127.0.0.1:4000/v1/chat/completions")
DEFAULT_MODEL = os.environ.get("HERMCLAW_AGENT_MODEL", "local-coder")
DEFAULT_WORKSPACE_ROOT = Path(os.environ.get("HERMCLAW_AGENT_WORKSPACES", "/home/kiworker/hermclaw_agent_workspaces"))
# Must match num_ctx of the LiteLLM alias in use (local-coder: 16384).
DEFAULT_CONTEXT_TOKENS = int(os.environ.get("HERMCLAW_AGENT_CONTEXT_TOKENS", "16384"))
DEFAULT_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_AGENT_MAX_OUTPUT_TOKENS", "4096"))
RECOVERY_MIN_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_RECOVERY_MIN_OUTPUT_TOKENS", "4096"))
RECOVERY_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_RECOVERY_MAX_OUTPUT_TOKENS", "6144"))
CONTEXT_SAFETY_TOKENS = 512
DEFAULT_CHARS_PER_TOKEN = 3.0
COMPACTION_TRIGGER_RATIO = float(os.environ.get("HERMCLAW_COMPACTION_TRIGGER_RATIO", "0.72"))
COMPACTION_TRIGGER_MAX_TOKENS = int(os.environ.get("HERMCLAW_COMPACTION_TRIGGER_MAX_TOKENS", "26000"))
COMPACTION_TARGET = float(os.environ.get("HERMCLAW_COMPACTION_TARGET", "0.55"))
INVALID_OUTPUT_LARGE_CHARS = int(os.environ.get("HERMCLAW_INVALID_OUTPUT_LARGE_CHARS", "7000"))
SUMMARY_MAX_TOKENS = 900
MAX_SUMMARY_CHARS = 3000
MAX_COMPACTED_LINES = 15
MAX_IDENTICAL_ACTIONS = 4
MAX_TOOL_OUTPUT = 12000
MIN_TOOL_OUTPUT = 3000
MAX_LINE_CHARS = 400
MAX_SEARCH_MATCHES = 60
MAX_WEB_BYTES = 180000
DEFAULT_MAX_REVIEW_CYCLES = int(os.environ.get("HERMCLAW_AGENT_MAX_REVIEW_CYCLES", "3"))
REVIEW_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_REVIEW_MAX_OUTPUT_TOKENS", "1400"))
REVIEW_ADJUDICATION_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_REVIEW_ADJUDICATION_MAX_OUTPUT_TOKENS", "1600"))
ACCEPTANCE_REVIEW_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_ACCEPTANCE_REVIEW_MAX_OUTPUT_TOKENS", "2200"))
REVIEW_LENGTH_RETRY_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_REVIEW_LENGTH_RETRY_MAX_OUTPUT_TOKENS", "4096"))
REVIEW_FORMAT_REPAIR_MAX_OUTPUT_TOKENS = int(os.environ.get("HERMCLAW_REVIEW_FORMAT_REPAIR_MAX_OUTPUT_TOKENS", "1800"))
REVIEW_RAW_DIAGNOSTIC_CHARS = int(os.environ.get("HERMCLAW_REVIEW_RAW_DIAGNOSTIC_CHARS", "8000"))
MAX_REVIEW_DIFF_CHARS = 60000


SECRET_RE = re.compile(
    r"(?i)(api[_-]?key|token|secret|password|passwd|authorization|client[_-]?secret)\s*[:=]\s*([^\s,;\"']+)"
)
BEARER_RE = re.compile(r"(?i)(authorization\s*:\s*bearer\s+)[A-Za-z0-9._~+/-]{8,}")
PRIVATE_KEY_RE = re.compile(r"-----BEGIN [^-]*(?:PRIVATE|SECRET)[^-]*-----.*?-----END [^-]*-----", re.S | re.I)


TEST_PATTERNS = [
    re.compile(p, re.I)
    for p in [
        r"\bpytest\b",
        r"\bpython(?:3)?\s+-m\s+(?:pytest|unittest|py_compile)\b",
        r"\bphp\s+-l\b",
        r"\bphpunit\b",
        r"\bnode\s+--check\b",
        r"\bnpm\s+(?:run\s+)?test\b",
        r"\bpnpm\s+(?:run\s+)?test\b",
        r"\byarn\s+test\b",
        r"\bcomposer\s+test\b",
        r"\bgo\s+test\b",
        r"\bcargo\s+test\b",
        r"\bdotnet\s+test\b",
        r"\bmvn\s+test\b",
        r"\bgradle(?:w)?\b.*\btest\b",
        r"\bgit\s+diff\s+--check\b",
    ]
]

GIT_MUTATING_RE = re.compile(r"(?:^|[;&|]\s*)git\s+(?:push|commit|checkout|switch|reset|clean|branch|remote|rebase|merge|tag|cherry-pick|revert)\b", re.I)

DANGEROUS_SHELL = [
    re.compile(r"(^|[;&|]\s*)rm\s+-rf\s+/(?:\s|$)", re.I),
    re.compile(r"\bmkfs(?:\.|\s)", re.I),
    re.compile(r"\b(?:shutdown|reboot|poweroff|halt)\b", re.I),
    re.compile(r"\bdd\s+if=.*\sof=/dev/", re.I),
    re.compile(r"\bchmod\s+-R\s+777\s+/", re.I),
    re.compile(r"\b(?:iptables|nft)\b", re.I),
    re.compile(r"\bsystemctl\s+(?:disable|mask)\b", re.I),
    re.compile(r"(^|[;&|]\s*)(?:sudo|su)(?:\s|$)", re.I),
    re.compile(r"(^|[;&|]\s*)(?:apt|apt-get|dnf|yum|pacman|zypper|apk)(?:\s|$)", re.I),
]


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds")


def redact(text: str) -> str:
    if not text:
        return text
    text = PRIVATE_KEY_RE.sub("[PRIVATE_KEY_REDACTED]", text)
    text = BEARER_RE.sub(r"\1[REDACTED]", text)
    text = SECRET_RE.sub(lambda m: f"{m.group(1)}=[REDACTED]", text)
    return text


def shutil_which(command: str) -> str | None:
    for directory in os.environ.get("PATH", "").split(os.pathsep):
        candidate = Path(directory) / command
        if candidate.is_file() and os.access(candidate, os.X_OK):
            return str(candidate)
    return None


def truncate(text: str, limit: int = MAX_TOOL_OUTPUT) -> str:
    if len(text) <= limit:
        return text
    half = max(1, (limit - 120) // 2)
    return text[:half] + f"\n...[TRUNCATED {len(text) - 2*half} chars]...\n" + text[-half:]


def shorten(text: str, limit: int) -> str:
    """Single-line head of a text, for digests and notes."""
    flat = " ".join(text.split())
    return flat if len(flat) <= limit else flat[: max(1, limit - 1)] + "…"


def clip_lines(text: str, limit: int = MAX_TOOL_OUTPUT) -> str:
    """Cut at a line boundary and say how much is missing.

    Unlike truncate() this never removes the middle: the model sees one
    contiguous prefix, so line numbers and ranges stay trustworthy.
    """
    if len(text) <= limit:
        return text
    room = max(1, limit - 80)
    lines = text.splitlines()
    kept: list[str] = []
    used = 0
    for line in lines:
        if used + len(line) + 1 > room:
            break
        kept.append(line)
        used += len(line) + 1
    if not kept:
        return text[:room] + f"\n...[GEKÜRZT: {len(text) - room} weitere Zeichen nicht angezeigt]..."
    return "\n".join(kept) + f"\n...[GEKÜRZT: {len(lines) - len(kept)} weitere Zeilen nicht angezeigt]..."


class AgentError(RuntimeError):
    pass


@dataclasses.dataclass
class EventLogger:
    path: Path
    quiet: bool = False

    def __post_init__(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)

    def emit(self, kind: str, message: str, **meta: Any) -> None:
        safe_message = redact(str(message))
        safe_meta: dict[str, Any] = {}
        for key, value in meta.items():
            if isinstance(value, str):
                safe_meta[key] = redact(value)
            elif isinstance(value, list):
                safe_meta[key] = [redact(v) if isinstance(v, str) else v for v in value]
            else:
                safe_meta[key] = value
        event = {"ts": utc_now(), "kind": kind, "message": safe_message, "meta": safe_meta}
        with self.path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(event, ensure_ascii=False) + "\n")
        if not self.quiet:
            label = kind.upper()
            print(f"[{label}] {safe_message}", flush=True)


@dataclasses.dataclass
class SourceRegistry:
    path: Path
    sources: list[dict[str, Any]] = dataclasses.field(default_factory=list)

    def add(self, url: str, title: str, used_for: str, excerpt: str = "") -> dict[str, Any]:
        normalized = {
            "url": url,
            "title": title.strip() or url,
            "domain": urllib.parse.urlparse(url).hostname or "",
            "used_for": used_for.strip() or "Recherche",
            "accessed_at": utc_now(),
            "excerpt": truncate(redact(excerpt.strip()), 1200),
        }
        for src in self.sources:
            if src["url"] == normalized["url"]:
                if used_for and used_for not in src["used_for"]:
                    src["used_for"] += "; " + used_for
                self._save()
                return src
        self.sources.append(normalized)
        self._save()
        return normalized

    def _save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(self.sources, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


@dataclasses.dataclass
class RuntimeState:
    task: str
    job_id: str
    workspace: Path
    branch: str
    mutation_epoch: int = 0
    verified_epoch: int = -1
    diff_reviewed_epoch: int = -1
    files_changed: set[str] = dataclasses.field(default_factory=set)
    test_commands: list[str] = dataclasses.field(default_factory=list)
    turns: int = 0
    notes: list[str] = dataclasses.field(default_factory=list)
    # Per-result size budget; the controller derives it from the context window.
    tool_output_chars: int = MAX_TOOL_OUTPUT

    def add_note(self, text: str) -> bool:
        clean = shorten(redact(text), 300)
        if not clean or clean in self.notes:
            return False
        self.notes.append(clean)
        self.notes = self.notes[-24:]
        return True

    @property
    def latest_mutation_verified(self) -> bool:
        return self.mutation_epoch == 0 or self.verified_epoch >= self.mutation_epoch

    @property
    def latest_mutation_diff_reviewed(self) -> bool:
        return self.mutation_epoch == 0 or self.diff_reviewed_epoch >= self.mutation_epoch


class ToolExecutor:
    def __init__(self, state: RuntimeState, logger: EventLogger, sources: SourceRegistry) -> None:
        self.state = state
        self.logger = logger
        self.sources = sources
        self.tools: dict[str, Callable[[dict[str, Any]], str]] = {
            "list_files": self.list_files,
            "search_files": self.search_files,
            "read_file": self.read_file,
            "write_file": self.write_file,
            "replace_text": self.replace_text,
            "delete_file": self.delete_file,
            "shell": self.shell,
            "install_tool": self.install_tool,
            "git_status": self.git_status,
            "git_diff": self.git_diff,
            "git_diff_file": self.git_diff_file,
            "web_search": self.web_search,
            "web_fetch": self.web_fetch,
        }
        # One-line factual record of the last call; the controller keeps it
        # once the full output has been compacted out of the conversation.
        self.last_digest = ""

    def execute(self, name: str, args: dict[str, Any]) -> str:
        if name not in self.tools:
            raise AgentError(f"Unbekanntes Werkzeug: {name}")

        # Tool events should be useful enough to diagnose an agent loop without
        # exposing hidden reasoning. Log operational arguments for read-only
        # exploration tools, but never file contents or arbitrary shell payloads here.
        if name == "search_files":
            query = redact(str(args.get("query", "")).strip())
            path = str(args.get("path", ".")).strip() or "."
            glob = str(args.get("glob", "")).strip()
            self.logger.emit("tool", f'Suche im Projekt: "{query}"', tool=name, query=query, path=path, glob=glob)
        elif name == "list_files":
            path = str(args.get("path", ".")).strip() or "."
            depth = max(1, min(int(args.get("max_depth", 3)), 6))
            self.logger.emit("tool", f"Dateiliste wird gelesen: {path} (Tiefe {depth})", tool=name, path=path, max_depth=depth)
        elif name == "read_file":
            path = str(args.get("path", "")).strip()
            start = max(1, int(args.get("start_line", 1)))
            max_lines = max(1, min(int(args.get("max_lines", 400)), 1200))
            self.logger.emit("tool", f"Datei wird gelesen: {path}", tool=name, path=path, start_line=start, max_lines=max_lines)
        else:
            self.logger.emit("tool", f"{name} wird ausgeführt.", tool=name)

        self.last_digest = ""
        result = self.tools[name](args)
        # Tools size their own output; this only catches whatever is left over.
        result = clip_lines(result, self.state.tool_output_chars)
        if not self.last_digest:
            self.last_digest = shorten(result.strip().splitlines()[0], 160) if result.strip() else "(leer)"
        return result

    @staticmethod
    def _readonly_key(name: str, args: dict[str, Any]) -> str | None:
        if name == "search_files":
            normalized = {
                "query": ToolExecutor._normalize_search_query(str(args.get("query", ""))),
                "path": str(args.get("path", ".")).strip() or ".",
                "glob": str(args.get("glob", "")).strip(),
            }
        elif name == "list_files":
            normalized = {
                "path": str(args.get("path", ".")).strip() or ".",
                "max_depth": max(1, min(int(args.get("max_depth", 3)), 6)),
            }
        elif name == "read_file":
            normalized = {
                "path": str(args.get("path", "")).strip(),
                "start_line": max(1, int(args.get("start_line", 1))),
                "max_lines": max(1, min(int(args.get("max_lines", 400)), 1200)),
            }
        else:
            return None
        return name + ":" + json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    @staticmethod
    def _safe_readonly_event_meta(name: str, args: dict[str, Any]) -> dict[str, Any]:
        if name == "search_files":
            return {
                "query": redact(str(args.get("query", "")).strip()),
                "path": str(args.get("path", ".")).strip() or ".",
                "glob": str(args.get("glob", "")).strip(),
            }
        if name == "list_files":
            return {
                "path": str(args.get("path", ".")).strip() or ".",
                "max_depth": max(1, min(int(args.get("max_depth", 3)), 6)),
            }
        if name == "read_file":
            return {
                "path": str(args.get("path", "")).strip(),
                "start_line": max(1, int(args.get("start_line", 1))),
                "max_lines": max(1, min(int(args.get("max_lines", 400)), 1200)),
            }
        return {}

    @staticmethod
    def _normalize_search_query(query: str) -> str:
        return " ".join(query.lower().split())

    def _resolve(self, rel: str, must_exist: bool = False) -> Path:
        rel = str(rel or "").strip().replace("\\", "/")
        if rel.startswith("/"):
            raise AgentError("Absolute Pfade sind im Projekt-Workspace nicht erlaubt.")
        candidate = (self.state.workspace / rel).resolve()
        root = self.state.workspace.resolve()
        try:
            relative = candidate.relative_to(root)
        except ValueError as exc:
            raise AgentError("Pfad liegt außerhalb des Projekt-Workspace.") from exc
        if ".git" in relative.parts:
            raise AgentError("Direkter Zugriff auf .git ist dem Modell nicht erlaubt; Git-Steuerung bleibt bei der Runtime.")
        if must_exist and not candidate.exists():
            raise AgentError(f"Datei/Pfad existiert nicht: {rel}")
        return candidate

    def list_files(self, args: dict[str, Any]) -> str:
        base = self._resolve(str(args.get("path", ".")), must_exist=True)
        max_depth = max(1, min(int(args.get("max_depth", 3)), 6))
        root_depth = len(base.parts)
        rows: list[str] = []
        for path in sorted(base.rglob("*")):
            if ".git" in path.parts:
                continue
            if len(path.parts) - root_depth > max_depth:
                continue
            rel = path.relative_to(self.state.workspace)
            suffix = "/" if path.is_dir() else ""
            rows.append(str(rel) + suffix)
            if len(rows) >= 800:
                rows.append("...[LIMIT 800]...")
                break
        self.last_digest = f"{len(rows)} Einträge unter {str(args.get('path', '.')).strip() or '.'} (Tiefe {max_depth})"
        return clip_lines("\n".join(rows), self.state.tool_output_chars) or "(leer)"

    def search_files(self, args: dict[str, Any]) -> str:
        query = str(args.get("query", "")).strip()
        if not query:
            raise AgentError("search_files benötigt query.")
        path = str(args.get("path", "."))
        base = self._resolve(path, must_exist=True)
        glob = str(args.get("glob", "")).strip()
        matches: list[str] = []
        # -H keeps the path:line:content shape when the search targets a single file.
        cmd = ["rg", "-n", "-H", "--hidden", "--glob", "!.git/**", "--max-count", "80"]
        if glob:
            cmd += ["--glob", glob]
        cmd += [query, str(base)]
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
            if proc.returncode not in (0, 1):
                return f"SEARCH_QUERY: {query}\nSEARCH_PATH: {path}\nERROR: rg exit={proc.returncode}\n{truncate(proc.stderr)}"
            out = proc.stdout.replace(str(self.state.workspace.resolve()) + os.sep, "")
            matches = [line for line in out.splitlines() if line.strip()]
        except FileNotFoundError:
            needle = query.lower()
            for f in [base] if base.is_file() else base.rglob("*"):
                if not f.is_file() or ".git" in f.parts:
                    continue
                if glob and not f.match(glob):
                    continue
                try:
                    text = f.read_text(encoding="utf-8", errors="ignore")
                except OSError:
                    continue
                for num, line in enumerate(text.splitlines(), 1):
                    if needle in line.lower():
                        matches.append(f"{f.relative_to(self.state.workspace)}:{num}:{line[:500]}")
                        if len(matches) >= 80:
                            break
                if len(matches) >= 80:
                    break

        counts: dict[str, int] = {}
        for line in matches:
            # rg format is path:line:content. Windows drive letters are irrelevant
            # because workspace paths are normalized to relative POSIX-style output.
            candidate = line.split(":", 1)[0].strip()
            if candidate:
                counts[candidate] = counts.get(candidate, 0) + 1
        files = list(counts)

        self.logger.emit(
            "search",
            f'Dateisuche abgeschlossen: "{redact(query)}" → {len(matches)} Treffer in {len(files)} Datei(en).',
            query=redact(query),
            path=path,
            glob=glob,
            match_count=len(matches),
            files=files[:20],
            sample_matches=[redact(m) for m in matches[:8]],
        )
        header = [
            f"SEARCH_QUERY: {query}",
            f"SEARCH_PATH: {path}",
            f"SEARCH_GLOB: {glob or '(keins)'}",
            f"MATCH_COUNT: {len(matches)}",
            f"FILE_COUNT: {len(files)}",
            "FILES:",
        ]
        header.extend(f"- {f} ({counts[f]})" for f in files[:30])
        if len(files) > 30:
            header.append(f"- ... {len(files) - 30} weitere")
        if len(matches) > MAX_SEARCH_MATCHES:
            header.append(
                f"MATCHES (erste {MAX_SEARCH_MATCHES} von {len(matches)}; für mehr die Suche mit path/glob eingrenzen):"
            )
        else:
            header.append("MATCHES:")
        if matches:
            # Long lines (minified assets, SQL dumps) must not crowd out the other hits.
            header.extend(m if len(m) <= 240 else m[:240] + "…" for m in matches[:MAX_SEARCH_MATCHES])
        else:
            header.append("Keine Treffer.")
        self.last_digest = (
            f'"{redact(query)}"' + (f" [{glob}]" if glob else "") + f" in {path} → {len(matches)} Treffer in {len(files)} Datei(en)"
            + (": " + ", ".join(files[:6]) if files else "")
        )
        return clip_lines("\n".join(header), self.state.tool_output_chars)

    def read_file(self, args: dict[str, Any]) -> str:
        rel = str(args.get("path", ""))
        path = self._resolve(rel, must_exist=True)
        if not path.is_file():
            raise AgentError("read_file erwartet eine Datei.")
        start = max(1, int(args.get("start_line", 1)))
        max_lines = max(1, min(int(args.get("max_lines", 400)), 1200))
        raw = path.read_text(encoding="utf-8", errors="replace")
        lines = raw.splitlines()
        # Stop at a line boundary once the output budget is used up and report
        # the range that was really shown. Cutting the middle out afterwards
        # would leave the model with a file it only believes it has read.
        room = max(1, self.state.tool_output_chars - 500)
        shown: list[str] = []
        used = 0
        for number, line in enumerate(lines[start - 1 : start - 1 + max_lines], start=start):
            if len(line) > MAX_LINE_CHARS:
                line = line[:MAX_LINE_CHARS] + f"…[+{len(line) - MAX_LINE_CHARS} Zeichen]"
            row = f"{number}: {line}"
            if shown and used + len(row) + 1 > room:
                break
            shown.append(row)
            used += len(row) + 1
        end_line = start + len(shown) - 1 if shown else start - 1
        numbered = "\n".join(shown)
        self.last_digest = f"{rel} Zeilen {start}-{end_line} von {len(lines)}"
        self.logger.emit(
            "read",
            f"Datei gelesen: {rel} (Zeilen {start}-{end_line} von {len(lines)})",
            path=rel,
            start_line=start,
            end_line=end_line,
            total_lines=len(lines),
        )
        trailer = (
            f"\n\nREAD_RANGE: {rel} lines {start}-{end_line} of {len(lines)}."
            + (f" NEXT_START_LINE: {end_line + 1}." if end_line < len(lines) else " EOF_REACHED: true.")
        )
        if end_line < len(lines) and len(lines) > 300:
            # Paging through a 1300-line file costs more context than the model has.
            trailer += (
                f"\nGroße Datei: Suche mit search_files (path=\"{rel}\") nach einem Bezeichner und lies dann gezielt "
                "ab der Trefferzeile, statt Seite für Seite zu lesen."
            )
        return numbered + trailer

    def _mark_mutation(self, rel: str) -> None:
        self.state.mutation_epoch += 1
        self.state.files_changed.add(rel)
        self.logger.emit("write", f"Datei geändert: {rel}", path=rel, mutation_epoch=self.state.mutation_epoch)

    def write_file(self, args: dict[str, Any]) -> str:
        rel = str(args.get("path", ""))
        content = args.get("content")
        if not isinstance(content, str):
            raise AgentError("write_file benötigt content als String.")
        path = self._resolve(rel)
        path.parent.mkdir(parents=True, exist_ok=True)
        existed = path.exists() and path.is_file()
        before = path.read_text(encoding="utf-8", errors="replace") if existed else None
        if before == content:
            return "Keine Änderung: Inhalt identisch."
        path.write_text(content, encoding="utf-8")
        verb = "Aktualisiert" if existed else "Neu angelegt"
        self._mark_mutation(rel)
        return f"{verb}: {rel} ({len(content)} Zeichen)."

    def replace_text(self, args: dict[str, Any]) -> str:
        rel = str(args.get("path", ""))
        old = args.get("old")
        new = args.get("new")
        count = int(args.get("count", 1))
        if not isinstance(old, str) or not isinstance(new, str) or old == "":
            raise AgentError("replace_text benötigt nicht-leeres old und new als Strings.")
        path = self._resolve(rel, must_exist=True)
        text = path.read_text(encoding="utf-8", errors="replace")
        occurrences = text.count(old)
        if occurrences == 0:
            raise AgentError(
                "replace_text: Suchtext wurde nicht gefunden. `old` muss zeichengenau aus der Datei stammen "
                "(gleiche Einrückung, ohne die Zeilennummern aus read_file). Lies die Stelle bei Bedarf erneut "
                "und nimm einen kürzeren, eindeutigen Ausschnitt."
            )
        if count > 0 and occurrences < count:
            raise AgentError(f"replace_text: nur {occurrences} Treffer, erwartet mindestens {count}.")
        replaced_count = min(occurrences, count if count > 0 else occurrences)
        replaced = text.replace(old, new, count if count > 0 else occurrences)
        path.write_text(replaced, encoding="utf-8")
        self._mark_mutation(rel)
        return f"Ersetzt in {rel}: {replaced_count} Treffer."

    def delete_file(self, args: dict[str, Any]) -> str:
        rel = str(args.get("path", ""))
        path = self._resolve(rel, must_exist=True)
        if not path.is_file() and not path.is_symlink():
            raise AgentError("delete_file löscht nur einzelne Dateien/Symlinks.")
        path.unlink()
        self._mark_mutation(rel)
        return f"Gelöscht: {rel}"

    def _git_snapshot(self) -> dict[str, str]:
        """Fingerprint dirty paths so shell calls only claim files they actually changed.

        A fresh checkout may already show platform-only noise (for example CRLF
        conversion in a Windows wrapper). Comparing only ``git status`` before
        and after a shell command made *all* dirty paths look like shell mutations,
        which could later leak unrelated files into the autonomous commit.
        """
        proc = subprocess.run(
            ["git", "status", "--porcelain", "--untracked-files=all"],
            cwd=self.state.workspace,
            text=True,
            capture_output=True,
            timeout=20,
        )
        if proc.returncode != 0:
            return {}
        snapshot: dict[str, str] = {}
        for line in proc.stdout.splitlines():
            if len(line) < 4:
                continue
            status = line[:2]
            rel = line[3:].strip()
            if " -> " in rel:
                rel = rel.split(" -> ", 1)[1]
            if not rel:
                continue
            path = self.state.workspace / rel
            fingerprint = status + ":"
            try:
                if path.is_symlink():
                    fingerprint += "symlink:" + os.readlink(path)
                elif path.is_file():
                    fingerprint += hashlib.sha256(path.read_bytes()).hexdigest()
                elif path.exists():
                    fingerprint += "exists"
                else:
                    fingerprint += "missing"
            except OSError:
                fingerprint += "unreadable"
            snapshot[rel] = fingerprint
        return snapshot

    def _mark_external_mutation(self, before: dict[str, str], after: dict[str, str], source: str) -> None:
        changed = {path for path, fingerprint in after.items() if before.get(path) != fingerprint}
        removed_dirty = set(before) - set(after)
        if not changed and not removed_dirty:
            return
        self.state.mutation_epoch += 1
        for path in sorted(changed):
            if path and not path.startswith(("__pycache__/", ".pytest_cache/", ".mypy_cache/", ".ruff_cache/", ".venv/", "node_modules/")):
                self.state.files_changed.add(path)
        self.logger.emit(
            "write",
            f"Workspace wurde durch {source} verändert.",
            mutation_epoch=self.state.mutation_epoch,
            files=sorted(self.state.files_changed),
            shell_changed=sorted(changed),
        )

    def _is_test_command(self, command: str) -> bool:
        return any(p.search(command) for p in TEST_PATTERNS)

    def _shell_allowed(self, command: str) -> tuple[bool, str]:
        low = command.lower()
        if "curl" in low and re.search(r"curl\s+[^|]+\|\s*(?:ba)?sh", low):
            return False, "Pipe-to-shell über curl ist gesperrt."
        if "wget" in low and re.search(r"wget\s+[^|]+\|\s*(?:ba)?sh", low):
            return False, "Pipe-to-shell über wget ist gesperrt."
        if GIT_MUTATING_RE.search(command):
            return False, "Git-Mutationen (Branch/Commit/Push/Reset/Merge) gehören der Runtime und sind im shell-Tool gesperrt."
        if re.search(r"(?:^|\s)(?:rm|mv)\b[^\n]*\.git(?:/|\s|$)", command, re.I):
            return False, ".git darf nicht über shell verändert werden."
        for pattern in DANGEROUS_SHELL:
            if pattern.search(command):
                return False, f"Gefährlicher Systembefehl blockiert: {pattern.pattern}"
        return True, ""

    def shell(self, args: dict[str, Any]) -> str:
        command = str(args.get("command", "")).strip()
        if not command:
            raise AgentError("shell benötigt command.")
        allowed, reason = self._shell_allowed(command)
        if not allowed:
            raise AgentError(reason)
        timeout = max(1, min(int(args.get("timeout", 120)), 900))
        self.logger.emit("shell", f"Befehl wird ausgeführt: {redact(command)}", command=redact(command), timeout=timeout)
        before = self._git_snapshot()
        proc = subprocess.run(
            ["bash", "-lc", command],
            cwd=self.state.workspace,
            text=True,
            capture_output=True,
            timeout=timeout,
            env={**os.environ, "HERMCLAW_AGENT_JOB_ID": self.state.job_id},
        )
        after = self._git_snapshot()
        self._mark_external_mutation(before, after, "shell")
        output = f"exit={proc.returncode}\nSTDOUT:\n{proc.stdout}\nSTDERR:\n{proc.stderr}"
        # Command output is the one place where head+tail is right: the error
        # usually sits at the end, the invocation context at the start.
        output = truncate(redact(output), self.state.tool_output_chars)
        self.last_digest = f'"{shorten(redact(command), 100)}" → exit={proc.returncode}'
        if self._is_test_command(command):
            self.state.test_commands.append(command)
            if proc.returncode == 0:
                self.state.verified_epoch = self.state.mutation_epoch
                self.logger.emit("test", "Prüfung erfolgreich.", command=redact(command), epoch=self.state.verified_epoch)
            else:
                self.logger.emit("test", "Prüfung fehlgeschlagen.", command=redact(command), exit_code=proc.returncode)
        return output

    def install_tool(self, args: dict[str, Any]) -> str:
        ecosystem = str(args.get("ecosystem", "")).strip().lower()
        packages_raw = args.get("packages", [])
        if isinstance(packages_raw, str):
            packages = [packages_raw]
        elif isinstance(packages_raw, list):
            packages = [str(x).strip() for x in packages_raw if str(x).strip()]
        else:
            packages = []
        if not packages:
            raise AgentError("install_tool benötigt mindestens ein Paket.")
        for pkg in packages:
            if not re.fullmatch(r"[A-Za-z0-9_.@/+:-]{1,120}", pkg):
                raise AgentError(f"Ungültiger Paketname: {pkg}")
        self.logger.emit("install", f"Abhängigkeiten werden installiert ({ecosystem}): {', '.join(packages)}", ecosystem=ecosystem, packages=packages)
        before = self._git_snapshot()
        if ecosystem == "python":
            venv = self.state.workspace / ".venv"
            if not venv.exists():
                proc = subprocess.run(["python3", "-m", "venv", str(venv)], cwd=self.state.workspace, text=True, capture_output=True, timeout=180)
                if proc.returncode != 0:
                    raise AgentError("Python-venv konnte nicht erstellt werden: " + truncate(proc.stderr, 2000))
            pip = venv / "bin" / "python"
            proc = subprocess.run([str(pip), "-m", "pip", "install", *packages], cwd=self.state.workspace, text=True, capture_output=True, timeout=900)
        elif ecosystem == "npm":
            proc = subprocess.run(["npm", "install", *packages], cwd=self.state.workspace, text=True, capture_output=True, timeout=900)
        elif ecosystem == "composer":
            proc = subprocess.run(["composer", "require", *packages, "--no-interaction"], cwd=self.state.workspace, text=True, capture_output=True, timeout=900)
        elif ecosystem == "system":
            allow = {
                "python3", "python3-venv", "python3-pip", "python3-tk", "php-cli", "nodejs", "npm",
                "bash", "composer", "git", "curl", "sqlite3", "ca-certificates", "make", "ripgrep",
            }
            denied = [p for p in packages if p not in allow]
            if denied:
                raise AgentError("Systempaket nicht auf Allowlist: " + ", ".join(denied))
            helper = os.environ.get("HERMCLAW_PACKAGE_HELPER", "hermclaw-package-install")
            if not shutil_which(helper):
                raise AgentError(
                    "System-Package-Helper nicht vorhanden. Setze HERMCLAW_PACKAGE_HELPER auf einen kontrollierten Installer "
                    "oder installiere das Paket administrativ."
                )
            proc = subprocess.run([helper, *packages], cwd=self.state.workspace, text=True, capture_output=True, timeout=900)
        else:
            raise AgentError("install_tool ecosystem muss python, npm, composer oder system sein.")
        after = self._git_snapshot()
        self._mark_external_mutation(before, after, "install_tool")
        output = truncate(
            redact(f"exit={proc.returncode}\nSTDOUT:\n{proc.stdout}\nSTDERR:\n{proc.stderr}"),
            min(10000, self.state.tool_output_chars),
        )
        if proc.returncode != 0:
            raise AgentError("Paketinstallation fehlgeschlagen:\n" + output)
        self.last_digest = f"{ecosystem}: {', '.join(packages)} installiert"
        return output

    def git_status(self, args: dict[str, Any]) -> str:
        proc = subprocess.run(["git", "status", "--short", "--branch"], cwd=self.state.workspace, text=True, capture_output=True, timeout=20)
        entries = [line for line in proc.stdout.splitlines() if line.strip() and not line.startswith("##")]
        self.last_digest = f"{len(entries)} geänderte/neue Datei(en)"
        return clip_lines(proc.stdout + proc.stderr, self.state.tool_output_chars)

    def git_diff(self, args: dict[str, Any]) -> str:
        staged = bool(args.get("staged", False))
        command = ["git", "diff"] + (["--cached"] if staged else []) + ["--"]
        proc = subprocess.run(command, cwd=self.state.workspace, text=True, capture_output=True, timeout=30)
        if not staged:
            # A full working-tree diff review is part of the finish contract.
            # Store the mutation epoch so a later edit invalidates the review.
            self.state.diff_reviewed_epoch = self.state.mutation_epoch
        untracked = subprocess.run(
            ["git", "ls-files", "--others", "--exclude-standard"],
            cwd=self.state.workspace, text=True, capture_output=True, timeout=20
        ).stdout.splitlines()
        body = proc.stdout or "Keine Änderungen an getrackten Dateien."
        if untracked:
            body += "\n\nUNTRACKED_FILES:\n" + "\n".join(f"- {p}" for p in untracked[:80])
            body += "\nNutze git_diff_file für den Inhalt einer neuen Datei."
        self.last_digest = f"{len(body.splitlines())} Zeilen Diff" + (f", {len(untracked)} neue Datei(en)" if untracked else "")
        if len(body) > self.state.tool_output_chars:
            hint = "\nDer Diff ist länger als die Ausgabe; nutze git_diff_file pro Datei."
            return clip_lines(body, self.state.tool_output_chars - len(hint)) + hint
        return body

    def git_diff_file(self, args: dict[str, Any]) -> str:
        rel = str(args.get("path", "")).strip().replace("\\", "/")
        if not rel:
            raise AgentError("git_diff_file benötigt path.")
        path = self._resolve(rel)
        staged = bool(args.get("staged", False))
        tracked = subprocess.run(
            ["git", "ls-files", "--error-unmatch", "--", rel],
            cwd=self.state.workspace, text=True, capture_output=True, timeout=20
        ).returncode == 0
        self.last_digest = rel
        if tracked:
            command = ["git", "diff"] + (["--cached"] if staged else []) + ["--", rel]
            proc = subprocess.run(command, cwd=self.state.workspace, text=True, capture_output=True, timeout=30)
            return clip_lines(proc.stdout or f"Keine Diff-Änderung für {rel}.", self.state.tool_output_chars)
        if path.exists() and path.is_file():
            raw = path.read_text(encoding="utf-8", errors="replace")
            numbered = "\n".join(f"{i}: {line}" for i, line in enumerate(raw.splitlines(), 1))
            return clip_lines(f"UNTRACKED_FILE: {rel}\nCONTENT:\n{numbered}", self.state.tool_output_chars)
        status = subprocess.run(
            ["git", "status", "--short", "--", rel], cwd=self.state.workspace, text=True, capture_output=True, timeout=20
        ).stdout.strip()
        return status or f"Kein Git-Diff/keine Datei für {rel}."

    @staticmethod
    def _public_ip(ip: str) -> bool:
        try:
            obj = ipaddress.ip_address(ip)
            return not (obj.is_private or obj.is_loopback or obj.is_link_local or obj.is_reserved or obj.is_multicast)
        except ValueError:
            return False

    @classmethod
    def _safe_public_url(cls, url: str) -> bool:
        try:
            parsed = urllib.parse.urlparse(url)
            if parsed.scheme not in ("http", "https") or not parsed.hostname or parsed.username or parsed.password:
                return False
            host = parsed.hostname.lower()
            if host in {"localhost"} or host.endswith((".local", ".lan", ".home", ".internal", ".localhost")):
                return False
            if re.fullmatch(r"\d+(?:\.\d+){3}", host) or ":" in host:
                return cls._public_ip(host)
            infos = socket.getaddrinfo(host, parsed.port or (443 if parsed.scheme == "https" else 80), type=socket.SOCK_STREAM)
            ips = {info[4][0] for info in infos}
            return bool(ips) and all(cls._public_ip(ip) for ip in ips)
        except (OSError, ValueError):
            return False

    @staticmethod
    def _strip_html(raw: str) -> tuple[str, str]:
        title = ""
        m = re.search(r"<title[^>]*>(.*?)</title>", raw, re.I | re.S)
        if m:
            title = html.unescape(re.sub(r"<[^>]+>", " ", m.group(1))).strip()
        cleaned = re.sub(r"<(script|style|noscript|svg|canvas|form|nav|footer|header)\b[^>]*>.*?</\1>", " ", raw, flags=re.I | re.S)
        text = html.unescape(re.sub(r"<[^>]+>", " ", cleaned))
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n\s*\n+", "\n", text)
        return title, text.strip()

    def _fetch(self, url: str, max_bytes: int = MAX_WEB_BYTES) -> tuple[str, str, str]:
        current = url
        for _ in range(3):
            if not self._safe_public_url(current):
                raise AgentError("Unsichere oder interne URL wurde für Web-Recherche blockiert.")
            req = urllib.request.Request(
                current,
                headers={"User-Agent": f"HermclawAgentCore/{VERSION}", "Accept": "text/html,text/plain,application/json;q=0.6,*/*;q=0.1"},
            )
            opener = urllib.request.build_opener(NoRedirectHandler())
            try:
                with opener.open(req, timeout=10) as resp:
                    body = resp.read(max_bytes + 1)
                    if len(body) > max_bytes:
                        body = body[:max_bytes]
                    ctype = resp.headers.get_content_type()
                    charset = resp.headers.get_content_charset() or "utf-8"
                    raw = body.decode(charset, errors="replace")
                    if ctype in ("text/html", "application/xhtml+xml"):
                        title, text = self._strip_html(raw)
                    else:
                        title, text = current, raw
                    return resp.geturl(), title, text
            except urllib.error.HTTPError as exc:
                if 300 <= exc.code < 400 and exc.headers.get("Location"):
                    current = urllib.parse.urljoin(current, exc.headers["Location"])
                    continue
                raise AgentError(f"HTTP-Fehler {exc.code} beim Abruf.") from exc
            except OSError as exc:
                raise AgentError(f"Web-Abruf fehlgeschlagen: {exc}") from exc
        raise AgentError("Redirect-Limit überschritten.")

    def web_search(self, args: dict[str, Any]) -> str:
        query = str(args.get("query", "")).strip()
        if not query:
            raise AgentError("web_search benötigt query.")
        query = redact(query)
        self.logger.emit("research", f"Internetrecherche: {query}", query=query)
        url = "https://html.duckduckgo.com/html/?q=" + urllib.parse.quote(query)
        _, _, text = self._fetch(url, 240000)
        # DuckDuckGo HTML survives as stripped text poorly. Fetch raw once for links.
        req = urllib.request.Request(url, headers={"User-Agent": f"HermclawAgentCore/{VERSION}"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            raw = resp.read(240000).decode(resp.headers.get_content_charset() or "utf-8", errors="replace")
        results: list[dict[str, str]] = []
        for m in re.finditer(r'<a[^>]+class="[^"]*result__a[^"]*"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', raw, re.I | re.S):
            href = html.unescape(m.group(1))
            title = html.unescape(re.sub(r"<[^>]+>", " ", m.group(2))).strip()
            parsed = urllib.parse.urlparse(href)
            if parsed.hostname and "duckduckgo.com" in parsed.hostname and parsed.query:
                q = urllib.parse.parse_qs(parsed.query)
                href = q.get("uddg", [href])[0]
            if href.startswith("//"):
                href = "https:" + href
            if href.startswith("http") and self._safe_public_url(href):
                results.append({"title": title, "url": href})
            if len(results) >= max(1, min(int(args.get("limit", 5)), 8)):
                break
        if not results:
            return "Keine verwertbaren Suchtreffer."
        self.last_digest = f'"{shorten(query, 100)}" → {len(results)} Treffer'
        return "\n".join(f"{i+1}. {r['title']}\n   {r['url']}" for i, r in enumerate(results))

    def web_fetch(self, args: dict[str, Any]) -> str:
        url = str(args.get("url", "")).strip()
        used_for = str(args.get("used_for", "")).strip() or "Recherche"
        if not url:
            raise AgentError("web_fetch benötigt url.")
        self.logger.emit("research", f"Quelle wird gelesen: {url}", url=url, used_for=used_for)
        final_url, title, text = self._fetch(url)
        excerpt = truncate(text, min(6000, self.state.tool_output_chars - 300))
        self.last_digest = shorten(f"{title or final_url} ({final_url})", 160)
        self.sources.add(final_url, title, used_for, excerpt)
        self.logger.emit("source", f"Quelle verwendet: {title or final_url}", url=final_url, used_for=used_for)
        return f"TITLE: {title}\nURL: {final_url}\nTEXT:\n{excerpt}"


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # type: ignore[override]
        return None


class LiteLLMClient:
    def __init__(
        self,
        endpoint: str = DEFAULT_LITELLM_URL,
        model: str = DEFAULT_MODEL,
        timeout: int = 1800,
        max_output_tokens: int = DEFAULT_MAX_OUTPUT_TOKENS,
    ) -> None:
        self.endpoint = endpoint
        self.model = model
        self.timeout = timeout
        self.max_output_tokens = max_output_tokens
        self.last_usage: dict[str, Any] = {}
        self.last_finish_reason = ""

    def complete(self, messages: list[dict[str, str]], max_tokens: int | None = None) -> str:
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": 0.15,
            "max_tokens": max_tokens or self.max_output_tokens,
        }
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(self.endpoint, data=data, headers={"Content-Type": "application/json"}, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                body = json.loads(resp.read().decode("utf-8"))
        except Exception as exc:
            raise AgentError(f"LLM-Request fehlgeschlagen: {exc}") from exc
        try:
            choice = body["choices"][0]
            msg = choice["message"]
            content = msg.get("content") or ""
            if not content and msg.get("reasoning_content"):
                raise AgentError("Modell lieferte nur reasoning_content, aber keine ausführbare JSON-Aktion.")
            usage = body.get("usage")
            self.last_usage = usage if isinstance(usage, dict) else {}
            self.last_finish_reason = str(choice.get("finish_reason") or "")
            return str(content)
        except (KeyError, IndexError, TypeError) as exc:
            raise AgentError(f"Ungültige LiteLLM-Antwort: {truncate(json.dumps(body, ensure_ascii=False), 2000)}") from exc


SYSTEM_PROMPT = r"""
