@dataclasses.dataclass
class Turn:
    number: int
    assistant: str
    result: str
    digest: str
    # Set while the full output of a read-only call is still in the conversation.
    readonly_key: str | None = None
    epoch: int = 0
    # An unusable answer plus the runtime's correction; dropped once the model recovers.
    invalid: bool = False


class AgentController:
    def __init__(
        self,
        client: LiteLLMClient,
        state: RuntimeState,
        logger: EventLogger,
        sources: SourceRegistry,
        max_turns: int = 60,
        context_tokens: int = DEFAULT_CONTEXT_TOKENS,
        max_output_tokens: int = DEFAULT_MAX_OUTPUT_TOKENS,
        transcript_path: Path | None = None,
        reviewer_client: LiteLLMClient | None = None,
        max_review_cycles: int = DEFAULT_MAX_REVIEW_CYCLES,
    ) -> None:
        self.client = client
        self.state = state
        self.logger = logger
        self.sources = sources
        self.executor = ToolExecutor(state, logger, sources)
        self.max_turns = max_turns
        self.context_tokens = context_tokens
        self.max_output_tokens = max_output_tokens
        # Raw model answers and runtime replies, for diagnosing a run afterwards.
        self.transcript_path = transcript_path
        self.reviewer_client = reviewer_client
        self.max_review_cycles = max(1, max_review_cycles)
        self.review_failures = 0
        self.summary = ""
        self.input_budget_tokens = max(1500, context_tokens - max_output_tokens - CONTEXT_SAFETY_TOKENS)
        trigger_ratio = max(0.50, min(COMPACTION_TRIGGER_RATIO, 0.90))
        trigger_cap = max(2500, COMPACTION_TRIGGER_MAX_TOKENS)
        self.compaction_trigger_tokens = min(int(self.input_budget_tokens * trigger_ratio), trigger_cap)
        target_ratio = max(0.30, min(COMPACTION_TARGET, trigger_ratio - 0.05))
        target = int(self.input_budget_tokens * target_ratio)
        self.compaction_target_tokens = max(1500, min(target, self.compaction_trigger_tokens - 800))
        self.chars_per_token = DEFAULT_CHARS_PER_TOKEN
        # A single tool result may use a quarter of the prompt, so several of
        # them stay visible side by side before compaction has to step in.
        budget_chars = int(self.input_budget_tokens * self.chars_per_token)
        state.tool_output_chars = max(MIN_TOOL_OUTPUT, min(MAX_TOOL_OUTPUT, budget_chars // 4))
        self.history: list[Turn] = []
        self.compacted: list[str] = []
        self.last_action_key = ""
        self.identical_actions = 0
        # Invalid/cut-off model replies are never replayed to the model. Only this
        # compact runtime correction is attached to the latest user observation.
        self.repair_feedback = ""
        self.pinned = self._render_pinned()

    def _render_pinned(self) -> str:
        """First user message: the task plus everything that must survive compaction.

        It is only re-rendered when turns are folded, so between compactions the
        conversation is append-only and the backend can reuse its prompt cache.
        """
        parts = [
            "BENUTZERAUFTRAG:\n" + self.state.task,
            f"RUNTIME:\nJob: {self.state.job_id}\nBranch: {self.state.branch}\n"
            f"Workspace: . (isolierter Git-Klon)\nAktuelles Datum (UTC): {dt.datetime.now(dt.timezone.utc).date().isoformat()}\n"
            f"Maximale Runden: {self.max_turns}",
        ]
        if self.summary:
            parts.append("DEIN ARBEITSSTAND (von dir bei der letzten Verdichtung geschrieben):\n" + self.summary)
        if self.compacted:
            shown = self.compacted[-MAX_COMPACTED_LINES:]
            older = len(self.compacted) - len(shown)
            parts.append(
                "ÄLTERER VERLAUF (von der Runtime verdichtet; die Ausgaben dieser Runden sind nicht mehr im Kontext, "
                "lies eine Datei bei Bedarf erneut):\n"
                + (f"- … {older} frühere Runden\n" if older else "")
                + "\n".join(shown)
            )
        if self.state.notes:
            parts.append("DEINE NOTIZEN:\n" + "\n".join(f"- {note}" for note in self.state.notes))
        parts.append("Gib pro Runde genau eine JSON-Aktion aus.")
        return "\n\n".join(parts)

    def _messages(self) -> list[dict[str, str]]:
        messages = [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": self.pinned},
        ]
        for turn in self.history:
            messages.append({"role": "assistant", "content": turn.assistant})
            messages.append({"role": "user", "content": turn.result})
        if self.repair_feedback:
            # Do not feed malformed/cut-off assistant output back into the model:
            # local models tend to continue or imitate it. Attach only the runtime
            # correction to the latest user-side observation instead.
            messages[-1] = dict(messages[-1])
            messages[-1]["content"] += (
                "\n\nRUNTIME-KORREKTUR NACH UNGÜLTIGER MODELLAUSGABE:\n" + self.repair_feedback
            )
        return messages

    def _estimate_tokens(self, messages: list[dict[str, str]]) -> int:
        chars = sum(len(m["content"]) + 16 for m in messages)
        return int(chars / self.chars_per_token) + 1

    def _fold(self, target_tokens: int) -> int:
        folded = 0
        # The newest turn always stays verbatim: it is what the model reacts to.
        while len(self.history) > 1 and self._estimate_tokens(self._messages()) > target_tokens:
            turn = self.history.pop(0)
            self.compacted.append(f"- Runde {turn.number}: {turn.digest}")
            folded += 1
            self.pinned = self._render_pinned()
        return folded

    def _summarize(self) -> None:
        """Let the model write down what it learned before the outputs disappear.

        The one-line records say what was done, not what was found. Without
        this the model starts its search over after every compaction.
        """
        messages = self._messages()
        messages[-1] = {"role": "user", "content": messages[-1]["content"] + "\n\n" + SUMMARY_REQUEST}
        self.logger.emit("model", "Modell fasst den Arbeitsstand vor der Verdichtung zusammen.", turn=self.state.turns)
        try:
            raw = self.client.complete(messages, max_tokens=SUMMARY_MAX_TOKENS)
        except AgentError as exc:
            self.logger.emit(
                "warning",
                "Arbeitsstand konnte nicht zusammengefasst werden; Verdichtung ohne Zusammenfassung.",
                error=redact(str(exc)),
            )
            return
        text = raw.strip()
        try:
            habit = self._extract_json(text)
        except Exception:
            habit = None
        if isinstance(habit, dict) and "action" in habit:
            # Answered with an action out of habit: keep only the text it carries.
            text = " ".join(str(habit[k]) for k in ("summary", "note", "status") if isinstance(habit.get(k), str))
        text = clip_lines(redact(text.strip()), MAX_SUMMARY_CHARS)
        if text:
            self.summary = text

    def _compact(self) -> None:
        """Compact early, before a local model reaches the unreliable edge of its context window."""
        if len(self.history) <= 1 or self._estimate_tokens(self._messages()) <= self.compaction_trigger_tokens:
            return
        # The summary request must still fit into the window together with its answer.
        folded = self._fold(self.context_tokens - SUMMARY_MAX_TOKENS - CONTEXT_SAFETY_TOKENS)
        self._summarize()
        folded += self._fold(self.compaction_target_tokens)
        self.pinned = self._render_pinned()
        self.logger.emit(
            "agent",
            f"Kontext verdichtet: {folded} ältere Runde(n) zusammengefasst.",
            folded_turns=folded,
            visible_turns=len(self.history),
            summary_chars=len(self.summary),
            estimated_prompt_tokens=self._estimate_tokens(self._messages()),
            compaction_trigger_tokens=self.compaction_trigger_tokens,
            compaction_target_tokens=self.compaction_target_tokens,
        )
        self._transcript({"turn": self.state.turns, "event": "compaction", "folded_turns": folded, "summary": self.summary})

    def _transcript(self, entry: dict[str, Any]) -> None:
        if self.transcript_path is None:
            return
        safe = {key: redact(value) if isinstance(value, str) else value for key, value in entry.items()}
        self.transcript_path.parent.mkdir(parents=True, exist_ok=True)
        with self.transcript_path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps({"ts": utc_now(), **safe}, ensure_ascii=False) + "\n")

    def _calibrate(self, messages: list[dict[str, str]]) -> dict[str, Any]:
        """Learn the real chars-per-token ratio from the backend's usage report."""
        usage = getattr(self.client, "last_usage", None) or {}
        meta: dict[str, Any] = {}
        prompt_tokens = usage.get("prompt_tokens")
        if isinstance(prompt_tokens, int) and prompt_tokens > 0:
            meta["prompt_tokens"] = prompt_tokens
            observed = sum(len(m["content"]) for m in messages) / prompt_tokens
            # Some backends report only the uncached part of the prompt. Such
            # ratios are implausible and must not skew the estimate.
            if 1.5 <= observed <= 6.0:
                self.chars_per_token = max(2.0, min(4.5, (self.chars_per_token + observed) / 2))
            if prompt_tokens > self.input_budget_tokens + CONTEXT_SAFETY_TOKENS:
                self.logger.emit(
                    "warning",
                    "Prompt größer als das geplante Kontextbudget; --context-tokens gegen num_ctx des Modell-Alias prüfen.",
                    prompt_tokens=prompt_tokens,
                    input_budget_tokens=self.input_budget_tokens,
                )
        if isinstance(usage.get("completion_tokens"), int):
            meta["completion_tokens"] = usage["completion_tokens"]
        return meta

    def _footer(self, turn: int) -> str:
        changed = sorted(self.state.files_changed)
        listed = ", ".join(changed[:8]) + (f" (+{len(changed) - 8})" if len(changed) > 8 else "") if changed else "keine"
        untested = self.state.mutation_epoch > 0 and not self.state.latest_mutation_verified
        footer = (
            f"[Runde {turn}/{self.max_turns} | Geänderte Dateien: {listed} | "
            f"Ungetestete Änderungen: {'ja' if untested else 'nein'}]"
        )
        remaining = self.max_turns - turn
        if remaining <= 10:
            footer += f"\nEs bleiben noch {remaining} Runden. Schließe jetzt ab: fehlende Änderung umsetzen, prüfen, finish."
        return footer

    def _record(
        self,
        turn: int,
        assistant: str,
        result: str,
        digest: str,
        readonly_key: str | None = None,
        invalid: bool = False,
        transcript_assistant: str | None = None,
    ) -> None:
        if not invalid:
            self.repair_feedback = ""
            # A corrected mistake must not stay in the conversation: the model
            # imitates its own history, failed attempts included.
            self.history = [earlier for earlier in self.history if not earlier.invalid]
        entry = Turn(
            number=turn,
            assistant=assistant,
            result=f"{result.rstrip()}\n\n{self._footer(turn)}",
            digest=shorten(redact(digest), 200),
            readonly_key=readonly_key,
            epoch=self.state.mutation_epoch,
            invalid=invalid,
        )
        self.history.append(entry)
        self._transcript({
            "turn": turn,
            "assistant": transcript_assistant if transcript_assistant is not None else assistant,
            "result": entry.result,
            "invalid": invalid,
        })

    def _record_invalid(self, turn: int, raw: str, feedback: str, digest: str) -> None:
        """Keep malformed output in local diagnostics, but never in model-facing history."""
        self.repair_feedback = feedback
        result = f"{feedback.rstrip()}\n\n{self._footer(turn)}"
        self._transcript({
            "turn": turn,
            "assistant": raw,
            "result": result,
            "invalid": True,
            "digest": shorten(redact(digest), 200),
        })

    def _normalize_action(self, action: dict[str, Any]) -> dict[str, Any]:
        """Accept the common near-misses of the action format instead of spending a model round on them."""
        kind = str(action.get("action", "")).strip()
        if kind.lower() in ("tool", "finish"):
            return action
        name = ""
        for candidate in (action.get("tool"), kind, action.get("name")):
            if isinstance(candidate, str) and candidate.strip() in self.executor.tools:
                name = candidate.strip()
                break
        if not name:
            return action
        args = next((action[key] for key in ("args", "arguments", "parameters") if isinstance(action.get(key), dict)), None)
        if args is None:
            # Parameters written next to the tool name instead of inside "args".
            reserved = {"action", "status", "tool", "name", "note", "args", "arguments", "parameters"}
            args = {key: value for key, value in action.items() if key not in reserved}
        fixed = {"action": "tool", "status": str(action.get("status", "Arbeite weiter.")), "tool": name, "args": args}
        if isinstance(action.get("note"), str):
            fixed["note"] = action["note"]
        return fixed

    def _count_identical(self, action_key: str, label: str) -> None:
        """Last line of defence against a model that keeps issuing the same action."""
        if action_key == self.last_action_key:
            self.identical_actions += 1
        else:
            self.last_action_key = action_key
            self.identical_actions = 1
        if self.identical_actions >= MAX_IDENTICAL_ACTIONS:
            raise AgentError(
                f"Modell wiederholt dieselbe Aktion {self.identical_actions}-mal in Folge ({label}); "
                "Auftrag wird abgebrochen, statt weitere Runden zu verbrauchen."
            )

    def _run_tool(self, tool: str, args: dict[str, Any]) -> tuple[str, str, str | None]:
        try:
            readonly_key = ToolExecutor._readonly_key(tool, args)
        except (TypeError, ValueError):
            readonly_key = None
        if readonly_key is not None:
            for earlier in reversed(self.history):
                if earlier.readonly_key == readonly_key and earlier.epoch == self.state.mutation_epoch:
                    # The answer is literally still on screen; repeating it would
                    # only push other results out of the context.
                    self.logger.emit(
                        "warning",
                        "Identischer Lesezugriff: Ergebnis steht bereits im sichtbaren Verlauf.",
                        tool=tool,
                        first_turn=earlier.number,
                        **ToolExecutor._safe_readonly_event_meta(tool, args),
                    )
                    return (
                        f"UNVERÄNDERT: Identischer Aufruf wie in Runde {earlier.number}. Das vollständige Ergebnis steht "
                        "weiter oben im Verlauf und ist noch aktuell (seitdem keine Dateiänderung). "
                        "Arbeite mit diesem Ergebnis weiter.",
                        f"wie Runde {earlier.number}",
                        None,
                    )
        try:
            result = self.executor.execute(tool, args)
            return result, self.executor.last_digest, readonly_key
        except Exception as exc:
            result = f"TOOL_ERROR: {type(exc).__name__}: {redact(str(exc))}"
            self.logger.emit("error", result, tool=tool)
            return clip_lines(result, self.state.tool_output_chars), result, None

    @staticmethod
    def _extract_json(raw: str) -> dict[str, Any]:
        """Parse one complete JSON object from otherwise noisy model output.

        Local models sometimes emit literal newlines inside JSON strings and may
        append prose, markdown fences or an extra closing brace after an otherwise
        complete action. Keep strict/lenient JSON parsing, then scan balanced
        objects while respecting quoted strings and escapes. No semantic repair or
        guessing is performed.
        """
        raw = raw.strip()
        if raw.startswith("```"):
            raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()

        def load_object(candidate: str) -> dict[str, Any] | None:
            for strict in (True, False):
                try:
                    obj = json.loads(candidate, strict=strict)
                except json.JSONDecodeError:
                    continue
                if isinstance(obj, dict):
                    return obj
            return None

        obj = load_object(raw)
        if obj is not None:
            return obj

        depth = 0
        start: int | None = None
        in_string = False
        escaped = False

        for idx, char in enumerate(raw):
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue

            if char == '"':
                in_string = True
                continue
            if char == "{":
                if depth == 0:
                    start = idx
                depth += 1
                continue
            if char == "}" and depth:
                depth -= 1
                if depth == 0 and start is not None:
                    obj = load_object(raw[start : idx + 1])
                    if obj is not None:
                        return obj
                    start = None

        raise AgentError("Modellantwort enthält kein gültiges JSON-Objekt.")

    @staticmethod
    def _extract_review_json(raw: str) -> dict[str, Any]:
        """Extrahiert das letzte gültige Reviewer-Urteil aus gemischter Modellausgabe."""
        text = str(raw or "").strip()
        valid: list[dict[str, Any]] = []

        def accept(obj: Any) -> None:
            if not isinstance(obj, dict):
                return
            verdict = str(obj.get("verdict", "")).strip().upper()
            if verdict in ("PASS", "FIX_REQUIRED"):
                valid.append(obj)

        try:
            accept(AgentController._extract_json(text))
        except Exception:
            pass

        depth = 0
        start: int | None = None
        in_string = False
        escaped = False

        for idx, char in enumerate(text):
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue
            if char == '"':
                in_string = True
                continue
            if char == "{":
                if depth == 0:
                    start = idx
                depth += 1
                continue
            if char == "}" and depth:
                depth -= 1
                if depth == 0 and start is not None:
                    candidate = text[start : idx + 1]
                    for strict in (True, False):
                        try:
                            accept(json.loads(candidate, strict=strict))
                            break
                        except json.JSONDecodeError:
                            continue
                    start = None

        if valid:
            return valid[-1]
        raise AgentError("Reviewer-Antwort enthält kein gültiges PASS/FIX_REQUIRED-JSON-Objekt.")

    def _review_json_call(
        self,
        messages: list[dict[str, str]],
        max_tokens: int,
        *,
        stage: str,
    ) -> dict[str, Any]:
        """Ein fachlicher Review mit Length-Retry oder genau einem Format-Recovery-Versuch."""
        if self.reviewer_client is None:
            raise AgentError("Reviewer-Client ist nicht aktiv.")

        def log_failure(
            raw_value: str,
            exc: Exception,
            *,
            attempt: int,
            error_code: str,
            message: str,
            requested_tokens: int,
        ) -> None:
            safe_raw = redact(str(raw_value or ""))
            raw_hash = hashlib.sha256(
                str(raw_value or "").encode("utf-8", errors="replace")
            ).hexdigest()
            self.logger.emit(
                "review",
                message,
                error_code=error_code,
                stage=stage,
                attempt=attempt,
                parse_error=redact(str(exc)),
                raw_chars=len(str(raw_value or "")),
                raw_sha256=raw_hash,
                finish_reason=str(
                    getattr(self.reviewer_client, "last_finish_reason", "") or ""
                ),
                requested_output_tokens=requested_tokens,
                raw_excerpt=truncate(safe_raw, REVIEW_RAW_DIAGNOSTIC_CHARS),
            )

        requested_tokens = max_tokens
        raw = self.reviewer_client.complete(messages, max_tokens=requested_tokens)

        try:
            return self._extract_review_json(raw)
        except Exception as first_exc:
            first_finish_reason = str(
                getattr(self.reviewer_client, "last_finish_reason", "") or ""
            )

            if first_finish_reason == "length":
                retry_tokens = min(
                    REVIEW_LENGTH_RETRY_MAX_OUTPUT_TOKENS,
                    max(requested_tokens + 800, int(requested_tokens * 1.75)),
                )
                log_failure(
                    raw,
                    first_exc,
                    attempt=1,
                    error_code="REVIEW_OUTPUT_TRUNCATED",
                    message=(
                        "Reviewer-Ausgabe wurde am Tokenlimit abgeschnitten. "
                        "Fachlicher Retry mit größerem Ausgabelimit wird versucht."
                    ),
                    requested_tokens=requested_tokens,
                )
                raw = self.reviewer_client.complete(
                    messages,
                    max_tokens=retry_tokens,
                )
                try:
                    return self._extract_review_json(raw)
                except Exception as retry_exc:
                    retry_finish_reason = str(
                        getattr(self.reviewer_client, "last_finish_reason", "") or ""
                    )
                    if retry_finish_reason == "length":
                        log_failure(
                            raw,
                            retry_exc,
                            attempt=2,
                            error_code="REVIEW_OUTPUT_TRUNCATED",
                            message="Reviewer-Ausgabe wurde auch beim erweiterten Retry abgeschnitten.",
                            requested_tokens=retry_tokens,
                        )
                        raise AgentError(
                            "REVIEW_OUTPUT_TRUNCATED: "
                            + stage
                            + ": Reviewer-Ausgabe blieb auch mit erweitertem "
                              "Ausgabelimit unvollständig."
                        ) from retry_exc

                    log_failure(
                        raw,
                        retry_exc,
                        attempt=2,
                        error_code="REVIEW_OUTPUT_INVALID",
                        message=(
                            "Reviewer-Retry wurde vollständig beendet, ist aber nicht als "
                            "gültiges Urteil lesbar. Format-Recovery wird versucht."
                        ),
                        requested_tokens=retry_tokens,
                    )
                    format_source = raw
            else:
                log_failure(
                    raw,
                    first_exc,
                    attempt=1,
                    error_code="REVIEW_OUTPUT_INVALID",
                    message="Reviewer-Ausgabeformat ungültig. Format-Recovery wird versucht.",
                    requested_tokens=requested_tokens,
                )
                format_source = raw

        safe_source = redact(str(format_source or ""))
        repair_messages = [
            {"role": "system", "content": REVIEW_FORMAT_REPAIR_SYSTEM_PROMPT},
            {
                "role": "user",
                "content": (
                    "VORHERIGE REVIEWER-ANTWORT:\n"
                    + truncate(safe_source, REVIEW_RAW_DIAGNOSTIC_CHARS)
                ),
            },
        ]
        repaired_raw = self.reviewer_client.complete(
            repair_messages,
            max_tokens=REVIEW_FORMAT_REPAIR_MAX_OUTPUT_TOKENS,
        )
        try:
            return self._extract_review_json(repaired_raw)
        except Exception as repair_exc:
            log_failure(
                repaired_raw,
                repair_exc,
                attempt=3 if first_finish_reason == "length" else 2,
                error_code="REVIEW_OUTPUT_INVALID",
                message="Reviewer-Ausgabeformat auch nach Format-Recovery ungültig.",
                requested_tokens=REVIEW_FORMAT_REPAIR_MAX_OUTPUT_TOKENS,
            )
            raise AgentError(
                "REVIEW_OUTPUT_INVALID: "
                + stage
                + ": Reviewer lieferte auch nach Recovery kein gültiges "
                  "PASS/FIX_REQUIRED-JSON-Objekt."
            ) from repair_exc

    def _run_independent_review(self, coder_review: str) -> dict[str, Any]:
        if self.reviewer_client is None:
            return {"verdict": "PASS", "summary": "Unabhängiger Review deaktiviert.", "issues": []}

        patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
        if len(patch) > MAX_REVIEW_DIFF_CHARS:
            patch = truncate(patch, MAX_REVIEW_DIFF_CHARS)
        prompt = (
            "ORIGINALAUFTRAG:\n" + redact(self.state.task)
            + "\n\nGEÄNDERTE DATEIEN:\n" + "\n".join(sorted(self.state.files_changed))
            + "\n\nERFOLGREICHE/VERWENDETE PRÜFBEFEHLE:\n"
            + ("\n".join(redact(x) for x in self.state.test_commands) or "(keine)")
            + "\n\nCODER-SELBSTREVIEW:\n" + redact(coder_review)
            + "\n\nFINALER DIFF:\n" + redact(patch)
        )
        messages = [
            {"role": "system", "content": REVIEW_SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ]
        parsed = self._review_json_call(
            messages,
            REVIEW_MAX_OUTPUT_TOKENS,
            stage="independent_review",
        )
        verdict = str(parsed.get("verdict", "")).strip().upper()
        issues_raw = parsed.get("issues", [])
        issues = [shorten(redact(str(item)), 500) for item in issues_raw] if isinstance(issues_raw, list) else []
        summary = shorten(redact(str(parsed.get("summary", ""))), 1200)
        if verdict not in ("PASS", "FIX_REQUIRED"):
            raise AgentError("Reviewer verdict muss PASS oder FIX_REQUIRED sein.")
        if verdict == "FIX_REQUIRED" and not issues:
            issues = [summary or "Reviewer fordert Korrekturen, hat aber keinen Einzelpunkt geliefert."]
        return {"verdict": verdict, "summary": summary, "issues": issues}

    @staticmethod
    def _validate_acceptance_checks(
        checks_raw: Any,
        final_patch: str,
    ) -> tuple[list[dict[str, str]], list[str]]:
        """Prüft PASS-Belege deterministisch gegen den tatsächlich aktuellen Diff."""
        validated: list[dict[str, str]] = []
        problems: list[str] = []

        if not isinstance(checks_raw, list) or not checks_raw:
            return [], ["Acceptance-PASS enthält keine strukturierten Anforderungsbelege."]

        seen_requirements: set[str] = set()
        for index, item in enumerate(checks_raw, 1):
            if not isinstance(item, dict):
                problems.append(f"Check {index} ist kein strukturiertes Objekt.")
                continue

            requirement = str(item.get("requirement", "")).strip()
            path = str(item.get("path", "")).strip()
            evidence = str(item.get("evidence", "")).strip()
            reason = str(item.get("reason", "")).strip()

            if not requirement or not path or not evidence or not reason:
                problems.append(
                    f"Check {index} benötigt requirement, path, evidence und reason."
                )
                continue
            if len(evidence) < 4:
                problems.append(f"Check {index} enthält einen zu kurzen Beleg.")
                continue

            requirement_key = " ".join(requirement.lower().split())
            if requirement_key in seen_requirements:
                problems.append(f"Check {index} wiederholt dieselbe Anforderung ohne zusätzlichen Nachweis.")
                continue
            seen_requirements.add(requirement_key)

            if path not in final_patch:
                problems.append(
                    f"{path}: behaupteter Acceptance-Pfad kommt im finalen Diff nicht vor "
                    f"(Anforderung: {shorten(redact(requirement), 180)})."
                )
                continue
            if evidence not in final_patch:
                problems.append(
                    f"{path}: behaupteter Acceptance-Beleg ist im finalen Diff nicht vorhanden "
                    f"(Anforderung: {shorten(redact(requirement), 180)}; "
                    f"Beleg: {shorten(redact(evidence), 180)})."
                )
                continue

            validated.append({
                "requirement": shorten(redact(requirement), 500),
                "path": shorten(redact(path), 300),
                "evidence": shorten(redact(evidence), 700),
                "reason": shorten(redact(reason), 700),
            })

        return validated, problems

    def _run_acceptance_review(self, coder_review: str, first_review: dict[str, Any]) -> dict[str, Any]:
        """Zweite frische Prüfung mit deterministisch validierten PASS-Belegen."""
        if self.reviewer_client is None:
            return {"verdict": "PASS", "summary": "Zweite Akzeptanzprüfung deaktiviert.", "issues": [], "checks": []}

        full_patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
        review_patch = full_patch
        if len(review_patch) > MAX_REVIEW_DIFF_CHARS:
            review_patch = truncate(review_patch, MAX_REVIEW_DIFF_CHARS)
        prompt = (
            "ORIGINALAUFTRAG:\n" + redact(self.state.task)
            + "\n\nGEÄNDERTE PFADE (Laufhistorie):\n" + "\n".join(sorted(self.state.files_changed))
            + "\n\nERFOLGREICHE/VERWENDETE PRÜFBEFEHLE:\n"
            + ("\n".join(redact(x) for x in self.state.test_commands) or "(keine)")
            + "\n\nCODER-SELBSTREVIEW:\n" + redact(coder_review)
            + "\n\nERSTER UNABHÄNGIGER REVIEW:\n" + redact(str(first_review.get("summary", "")))
            + "\n\nFINALER DIFF:\n" + redact(review_patch)
        )
        messages = [
            {"role": "system", "content": ACCEPTANCE_REVIEW_SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ]
        parsed = self._review_json_call(
            messages,
            ACCEPTANCE_REVIEW_MAX_OUTPUT_TOKENS,
            stage="acceptance_review",
        )
        verdict = str(parsed.get("verdict", "")).strip().upper()
        issues_raw = parsed.get("issues", [])
        issues = [shorten(redact(str(item)), 700) for item in issues_raw] if isinstance(issues_raw, list) else []
        summary = shorten(redact(str(parsed.get("summary", ""))), 1400)
        if verdict not in ("PASS", "FIX_REQUIRED"):
            raise AgentError("Akzeptanzprüfung verdict muss PASS oder FIX_REQUIRED sein.")

        checks_raw = parsed.get("checks", [])
        checks: list[Any] = []
        if verdict == "PASS":
            checks, evidence_problems = self._validate_acceptance_checks(
                checks_raw,
                redact(full_patch),
            )
            if evidence_problems:
                self.logger.emit(
                    "review",
                    "Acceptance-PASS wegen nicht belegbarer Checks verworfen.",
                    error_code="ACCEPTANCE_EVIDENCE_INVALID",
                    problems=evidence_problems[:10],
                )
                return {
                    "verdict": "FIX_REQUIRED",
                    "summary": (
                        "Der Acceptance Reviewer meldete PASS, konnte die behaupteten Erfüllungen "
                        "aber nicht mit überprüfbaren exakten Belegen aus dem finalen Diff nachweisen."
                    ),
                    "issues": [
                        shorten(
                            "Acceptance-Nachweis ungültig: " + problem
                            + " Prüfe die genannte Originalanforderung am aktuellen Code und implementiere sie, falls sie fehlt.",
                            700,
                        )
                        for problem in evidence_problems[:8]
                    ],
                    "checks": checks,
                }
        elif isinstance(checks_raw, list):
            checks = checks_raw

        if verdict == "FIX_REQUIRED" and not issues:
            issues = [summary or "Akzeptanzprüfung fordert Korrekturen ohne Einzelpunkt."]
        return {"verdict": verdict, "summary": summary, "issues": issues, "checks": checks}

    @staticmethod
    def _validate_adjudication_issues(
        issues_raw: Any,
        full_patch: str,
    ) -> tuple[list[str], list[str], list[str]]:
        """Validiert bestätigte Schiedsrichter-Findings deterministisch gegen den aktuellen Diff."""
        confirmed: list[str] = []
        rejected: list[str] = []
        invalid: list[str] = []

        if not isinstance(issues_raw, list) or not issues_raw:
            invalid.append("FIX_REQUIRED enthält keine strukturierte issues-Liste.")
            return confirmed, rejected, invalid

        for index, item in enumerate(issues_raw, 1):
            if not isinstance(item, dict):
                invalid.append(f"Issue {index} ist kein strukturiertes Objekt.")
                continue

            path = str(item.get("path", "")).strip()
            evidence = str(item.get("evidence", "")).strip()
            missing_literal = str(item.get("missing_literal", "")).strip()
            reason = str(item.get("reason", "")).strip()

            if not path or not evidence or not missing_literal or not reason:
                invalid.append(
                    f"Issue {index} benötigt path, evidence, missing_literal und reason."
                )
                continue

            if path not in full_patch:
                rejected.append(f"{path}: Pfad ist im aktuellen finalen Diff nicht belegt.")
                continue
            if evidence not in full_patch:
                rejected.append(f"{path}: angegebener evidence-Ausschnitt ist im aktuellen finalen Diff nicht vorhanden.")
                continue
            if missing_literal in full_patch:
                rejected.append(
                    f"{path}: angeblich fehlendes Literal ist im aktuellen finalen Diff bereits vorhanden: "
                    + shorten(redact(missing_literal), 180)
                )
                continue

            confirmed.append(
                shorten(
                    redact(
                        f"{path} — Beleg: \"{evidence}\" — fehlt: \"{missing_literal}\" — {reason}"
                    ),
                    800,
                )
            )

        return confirmed, rejected, invalid

    def _adjudicate_review(self, issues: list[str], summary: str = "") -> dict[str, Any]:
        """Prüft nach dem letzten Review-Zyklus nur die noch beanstandeten Punkte erneut."""
        if self.reviewer_client is None:
            return {"verdict": "PASS", "summary": "Kein Reviewer für Schiedsrichter-Prüfung aktiv.", "issues": []}

        full_patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
        review_patch = full_patch
        if len(review_patch) > MAX_REVIEW_DIFF_CHARS:
            review_patch = truncate(review_patch, MAX_REVIEW_DIFF_CHARS)
        prompt = (
            "ORIGINALAUFTRAG:\n" + redact(self.state.task)
            + "\n\nLETZTE REVIEW-ZUSAMMENFASSUNG:\n" + redact(summary)
            + "\n\nBEANSTANDETE PUNKTE:\n- " + "\n- ".join(redact(x) for x in issues)
            + "\n\nAKTUELLER FINALER DIFF:\n" + redact(review_patch)
        )
        messages = [
            {"role": "system", "content": REVIEW_ADJUDICATION_SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ]
        parsed = self._review_json_call(
            messages,
            REVIEW_ADJUDICATION_MAX_OUTPUT_TOKENS,
            stage="review_adjudication",
        )
        verdict = str(parsed.get("verdict", "")).strip().upper()
        checked_summary = shorten(redact(str(parsed.get("summary", ""))), 1400)
        if verdict not in ("PASS", "FIX_REQUIRED"):
            raise AgentError("Review-Schiedsrichter verdict muss PASS oder FIX_REQUIRED sein.")
        if verdict == "PASS":
            return {"verdict": "PASS", "summary": checked_summary, "issues": []}

        confirmed, rejected, invalid = self._validate_adjudication_issues(
            parsed.get("issues", []),
            full_patch,
        )

        if rejected:
            self.logger.emit(
                "review",
                "Widersprüchliche oder unbelegte Schiedsrichter-Findings verworfen.",
                rejected=rejected[:8],
            )

        if invalid:
            self.logger.emit(
                "review",
                "Schiedsrichter lieferte keine ausreichend belegte Issue-Struktur.",
                error_code="REVIEW_ADJUDICATION_EVIDENCE_INVALID",
                invalid=invalid[:8],
            )
            raise AgentError(
                "REVIEW_ADJUDICATION_EVIDENCE_INVALID: "
                + "; ".join(invalid[:6])
            )

        if confirmed:
            return {
                "verdict": "FIX_REQUIRED",
                "summary": checked_summary,
                "issues": confirmed,
            }

        return {
            "verdict": "PASS",
            "summary": shorten(
                "Alle vom Schiedsrichter erneut behaupteten Punkte wurden durch die deterministische "
                "Diff-Evidenzprüfung als bereits erfüllt oder unbelegt verworfen. "
                + checked_summary,
                1400,
            ),
            "issues": [],
        }

    def run(self) -> dict[str, Any]:
        self.logger.emit(
            "agent",
            "Auftrag wird analysiert.",
            job_id=self.state.job_id,
            branch=self.state.branch,
            version=VERSION,
            input_budget_tokens=self.input_budget_tokens,
            max_output_tokens=self.max_output_tokens,
        )
        invalid_rounds = 0
        next_output_tokens = self.max_output_tokens
        for turn in range(1, self.max_turns + 1):
            self.state.turns = turn
            self._compact()
            messages = self._messages()
            self.logger.emit(
                "model",
                "Modell entscheidet den nächsten Arbeitsschritt.",
                turn=turn,
                visible_turns=len(self.history),
                estimated_prompt_tokens=self._estimate_tokens(messages),
            )
            requested_output_tokens = max(256, int(next_output_tokens))
            raw = self.client.complete(messages, max_tokens=requested_output_tokens)
            usage_meta = self._calibrate(messages)
            try:
                parsed = self._extract_json(raw)
                action = self._normalize_action(parsed)
            except Exception as exc:
                invalid_rounds += 1
                finish_reason = str(getattr(self.client, "last_finish_reason", "") or "")
                cut_off = finish_reason == "length"
                if cut_off:
                    recovery_floor = max(self.max_output_tokens, RECOVERY_MIN_OUTPUT_TOKENS)
                    next_output_tokens = min(
                        RECOVERY_MAX_OUTPUT_TOKENS,
                        max(recovery_floor, int(requested_output_tokens * 1.5)),
                    )
                    feedback = (
                        f"AUSGABE_ABGESCHNITTEN: Die vorige Antwort wurde am Ausgabelimit von {requested_output_tokens} Tokens "
                        "abgeschnitten und vollständig verworfen. Setze sie NICHT fort und wiederhole sie NICHT. "
                        "Gib jetzt genau EINE möglichst kleine JSON-Tool-Aktion aus. Die Runtime erlaubt für den "
                        f"nächsten Reparaturversuch bis zu {next_output_tokens} Ausgabetokens, aber nutze diesen Spielraum "
                        "nur falls die Aktion ihn wirklich benötigt. Bei einer großen neuen Datei zuerst nur ein "
                        "kurzes Gerüst mit write_file anlegen und danach abschnittsweise mit replace_text erweitern. "
                        + ACTION_FORMAT_HINT
                    )
                else:
                    next_output_tokens = self.max_output_tokens
                    if len(raw) >= INVALID_OUTPUT_LARGE_CHARS:
                        feedback = (
                            f"INVALID_MODEL_OUTPUT: {exc}. Die vorige Antwort war mit {len(raw)} Zeichen sehr groß, "
                            "nicht als JSON lesbar und wurde vollständig verworfen. Gib jetzt nur EINE kleine Aktion aus. "
                            "Große Codeänderungen auf mehrere write_file/replace_text-Runden verteilen; pro schreibender "
                            "Aktion ungefähr höchstens 6000 Zeichen Quelltext. " + ACTION_FORMAT_HINT
                        )
                    else:
                        feedback = (
                            f"INVALID_MODEL_OUTPUT: {exc}. Die vorige Antwort wurde vollständig verworfen. "
                            "Keine Erklärung und kein Markdown; antworte jetzt ausschließlich mit genau EINEM gültigen "
                            "JSON-Objekt. " + ACTION_FORMAT_HINT
                        )
                self._record_invalid(turn, raw, feedback, "ungültige Modellausgabe")
                self.logger.emit(
                    "warning",
                    "Modellantwort war nicht als Aktion lesbar; erneuter Versuch.",
                    turn=turn,
                    cut_off=cut_off,
                    finish_reason=finish_reason,
                    invalid_rounds=invalid_rounds,
                    parse_error=shorten(redact(str(exc)), 300),
                    raw_chars=len(raw),
                    requested_output_tokens=requested_output_tokens,
                    next_output_tokens=next_output_tokens,
                    **usage_meta,
                )
                if invalid_rounds >= 3:
                    raise AgentError("Drei ungültige Modellaktionen in Folge.")
                continue
            kind = str(action.get("action", "")).strip().lower()
            if kind not in ("tool", "finish"):
                invalid_rounds += 1
                feedback = (
                    "INVALID_ACTION: Das Feld `action` muss \"tool\" oder \"finish\" sein. "
                    "Die vorige Antwort wurde verworfen. " + ACTION_FORMAT_HINT
                )
                self._record_invalid(turn, raw, feedback, "ungültige Aktion")
                # Name the offending shape, so the cause is visible without the transcript.
                self.logger.emit(
                    "warning",
                    "Modellantwort ohne gültige Aktion; erneuter Versuch.",
                    turn=turn,
                    action_value=shorten(str(action.get("action", "")), 80),
                    keys=sorted(str(key) for key in action)[:12],
                    invalid_rounds=invalid_rounds,
                    **usage_meta,
                )
                if invalid_rounds >= 3:
                    raise AgentError("Drei ungültige Modellaktionen in Folge.")
                continue
            invalid_rounds = 0
            next_output_tokens = self.max_output_tokens
            note = action.get("note")
            if isinstance(note, str) and self.state.add_note(note):
                self.logger.emit("agent", f"Notiz: {self.state.notes[-1]}", turn=turn)
            status = str(action.get("status", "Arbeite weiter.")).strip()
            self.logger.emit("agent", status, turn=turn, **usage_meta)
            # A repaired near-miss goes into the history in canonical form, so the
            # model sees the expected shape rather than its own variant.
            assistant = raw.strip() if action is parsed else json.dumps(action, ensure_ascii=False)
            if kind == "tool":
                tool = str(action.get("tool", "")).strip()
                args = action.get("args") if isinstance(action.get("args"), dict) else {}
                self._count_identical(tool + ":" + json.dumps(args, ensure_ascii=False, sort_keys=True, default=str), tool)
                result, digest, readonly_key = self._run_tool(tool, args)
                self._record(turn, assistant, f"ERGEBNIS {tool}:\n{result}", f"{tool}: {digest}", readonly_key)
                continue
            if kind == "finish":
                self._count_identical("finish", "finish")
                if not self.state.latest_mutation_verified:
                    msg = (
                        "FINISH_REJECTED: Seit der letzten Dateiänderung wurde keine passende erfolgreiche Prüfung ausgeführt. "
                        "Führe jetzt einen Syntaxcheck/Test aus und prüfe danach den finalen Zustand mit git_diff."
                    )
                    self._record(turn, assistant, msg, "finish abgelehnt: Prüfung nach letzter Änderung fehlt")
                    self.logger.emit("test", msg)
                    continue
                if not self.state.latest_mutation_diff_reviewed:
                    msg = (
                        "FINISH_REJECTED: Der Gesamt-Diff wurde seit der letzten Dateiänderung noch nicht geprüft. "
                        "Führe git_diff aus, gleiche den Diff mit dem Benutzerauftrag ab und versuche finish danach erneut."
                    )
                    self._record(turn, assistant, msg, "finish abgelehnt: finaler git_diff fehlt")
                    self.logger.emit("test", msg)
                    continue
                review = redact(str(action.get("review", "")).strip())
                if not review:
                    msg = (
                        "FINISH_REJECTED: Das Feld `review` fehlt. Vergleiche den finalen Diff mit den Kernanforderungen "
                        "des Benutzerauftrags. Wenn etwas fehlt oder fachlich falsch ist, korrigiere es; andernfalls nenne "
                        "kurz, wie die Anforderungen erfüllt sind, und versuche finish erneut."
                    )
                    self._record(turn, assistant, msg, "finish abgelehnt: fachlicher Review fehlt")
                    self.logger.emit("test", msg)
                    continue
                normalized = normalize_trailing_whitespace(
                    self.state.workspace, sorted(self.state.files_changed), self.logger
                )
                if normalized and self.state.test_commands:
                    # Mechanical whitespace cleanup should not cost another model round,
                    # but re-run the latest already-approved test command so the final
                    # workspace remains objectively verified.
                    last_test = self.state.test_commands[-1]
                    try:
                        self.executor.shell({"command": last_test})
                        self.logger.emit("test", "Letzte Prüfung nach automatischer Whitespace-Bereinigung erneut erfolgreich.")
                    except Exception as exc:
                        msg = (
                            "FINISH_REJECTED: Die automatische Whitespace-Bereinigung wurde durchgeführt, "
                            "aber die erneute letzte Prüfung ist fehlgeschlagen. Korrigiere den Fehler und prüfe erneut:\n"
                            + truncate(str(exc), 3000)
                        )
                        self._record(turn, assistant, msg, "finish abgelehnt: Test nach Whitespace-Bereinigung fehlgeschlagen")
                        self.logger.emit("test", "Prüfung nach automatischer Whitespace-Bereinigung fehlgeschlagen.")
                        continue
                diff_ok, diff_output = check_workspace_diff(self.state.workspace, sorted(self.state.files_changed))
                if not diff_ok:
                    msg = (
                        "FINISH_REJECTED: Die vollständige Diff-Prüfung (inklusive neuer/ungetrackter Dateien) meldet Probleme. "
                        "Korrigiere sie, führe danach erneut eine passende Prüfung und git_diff aus und versuche finish erneut:\n"
                        + truncate(diff_output, 3000)
                    )
                    self._record(turn, assistant, msg, "finish abgelehnt: vollständige Diff-Prüfung meldet Probleme")
                    self.logger.emit("test", "Vollständige Diff-Prüfung fehlgeschlagen; Agent darf korrigieren.")
                    continue
                initial_review = self._run_independent_review(review)
                independent_review = initial_review
                if initial_review["verdict"] == "PASS":
                    acceptance_review = self._run_acceptance_review(review, initial_review)
                    self.logger.emit(
                        "review",
                        "Zweite Akzeptanzprüfung abgeschlossen.",
                        verdict=acceptance_review.get("verdict", ""),
                        issues=acceptance_review.get("issues", []),
                        checks=acceptance_review.get("checks", []),
                        summary=acceptance_review.get("summary", ""),
                    )
                    independent_review = acceptance_review
                if independent_review["verdict"] == "FIX_REQUIRED":
                    self.review_failures += 1
                    issues = independent_review.get("issues", [])
                    self.logger.emit(
                        "review",
                        "Unabhängiger Review fordert Korrekturen.",
                        cycle=self.review_failures,
                        issues=issues,
                        summary=independent_review.get("summary", ""),
                    )
                    if self.review_failures >= self.max_review_cycles:
                        adjudication = self._adjudicate_review(
                            issues,
                            str(independent_review.get("summary", "")),
                        )
                        self.logger.emit(
                            "review",
                            "Finale Review-Schiedsrichter-Prüfung abgeschlossen.",
                            cycle=self.review_failures,
                            verdict=adjudication.get("verdict", ""),
                            issues=adjudication.get("issues", []),
                            summary=adjudication.get("summary", ""),
                        )
                        if adjudication["verdict"] == "FIX_REQUIRED":
                            confirmed = adjudication.get("issues", []) or issues
                            raise AgentError(
                                f"Unabhängiger Review fordert nach {self.review_failures} Review-Zyklen weiterhin bestätigte Korrekturen: "
                                + "; ".join(confirmed[:6])
                            )
                        self.logger.emit(
                            "review",
                            "Beanstandungen durch finale Schiedsrichter-Prüfung verworfen; Review bestanden.",
                            cycle=self.review_failures,
                            summary=adjudication.get("summary", ""),
                        )
                        return {
                            "summary": redact(str(action.get("summary", "Auftrag abgeschlossen."))),
                            "review": review,
                            "independent_review": adjudication,
                            "commit_message": redact(str(action.get("commit_message", "Hermclaw agent changes")))[:180],
                            "turns": turn,
                            "files_changed": sorted(self.state.files_changed),
                            "tests": [redact(x) for x in self.state.test_commands],
                            "sources": self.sources.sources,
                        }
                    msg = (
                        "INDEPENDENT_REVIEW_FIX_REQUIRED: Ein frischer Reviewer hat den finalen Diff gegen den "
                        "Originalauftrag geprüft und folgende konkrete Lücken gefunden:\n- "
                        + "\n- ".join(issues)
                        + "\nBehebe diese Punkte. Führe danach wieder passende Tests und git_diff aus, bevor du finish erneut versuchst."
                    )
                    self._record(
                        turn,
                        assistant,
                        msg,
                        "finish abgelehnt: unabhängiger Review fordert Korrekturen",
                    )
                    continue
                self.logger.emit(
                    "review",
                    "Unabhängige Abschlussprüfungen bestanden.",
                    summary=independent_review.get("summary", ""),
                    cycle=self.review_failures + 1,
                )
                return {
                    "summary": redact(str(action.get("summary", "Auftrag abgeschlossen."))),
                    "review": review,
                    "independent_review": independent_review,
                    "commit_message": redact(str(action.get("commit_message", "Hermclaw agent changes")))[:180],
                    "turns": turn,
                    "files_changed": sorted(self.state.files_changed),
                    "tests": [redact(x) for x in self.state.test_commands],
                    "sources": self.sources.sources,
                }
        raise AgentError(f"Maximale Agentenrunden erreicht ({self.max_turns}).")


def normalize_trailing_whitespace(workspace: Path, paths: list[str], logger: EventLogger | None = None) -> list[str]:
    """Remove only horizontal whitespace at line ends in agent-mutated UTF-8 text files.

    ``git diff --check`` rejects this mechanically, but asking the model to repair
    invisible spaces wastes turns and exact ``replace_text`` cannot reliably target
    whitespace that ``read_file`` does not make visible.  Keep this deliberately
    narrow: no fuzzy replacements, no unrelated files, no binary data.
    """
    changed: list[str] = []
    for rel in sorted({str(path).strip().replace("\\", "/") for path in paths if str(path).strip()}):
        path = (workspace / rel).resolve()
        try:
            path.relative_to(workspace.resolve())
        except ValueError:
            continue
        if not path.is_file() or path.is_symlink():
            continue
        raw = path.read_bytes()
        if b"\x00" in raw:
            continue
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            continue
        normalized = re.sub(r"[ \t]+(?=\r?$)", "", text, flags=re.M)
        if normalized == text:
            continue
        path.write_bytes(normalized.encode("utf-8"))
        changed.append(rel)
    if changed and logger is not None:
        logger.emit(
            "runtime",
            "Trailing whitespace in Agent-Dateien automatisch bereinigt: " + ", ".join(changed),
            paths=changed,
        )
    return changed


def workspace_patch_text(workspace: Path, paths: list[str]) -> str:
    """Return the exact selected working-tree diff, including untracked files, without touching the real index."""
    fd, index_name = tempfile.mkstemp(prefix="hermclaw-artifact-index-")
    os.close(fd)
    index_path = Path(index_name)
    try:
        index_path.unlink(missing_ok=True)
        env = {**os.environ, "GIT_INDEX_FILE": str(index_path)}
        read_tree = subprocess.run(
            ["git", "read-tree", "HEAD"], cwd=workspace, text=True, capture_output=True, timeout=30, env=env
        )
        if read_tree.returncode != 0:
            return "# Patch unavailable: " + redact(read_tree.stdout + read_tree.stderr)
        selected = _selected_git_paths(workspace, paths)
        if selected:
            add = subprocess.run(
                ["git", "add", "-A", "--", *selected], cwd=workspace, text=True, capture_output=True, timeout=60, env=env
            )
            if add.returncode != 0:
                return "# Patch unavailable: " + redact(add.stdout + add.stderr)
        diff = subprocess.run(
            ["git", "diff", "--cached", "--binary", "--no-ext-diff", "--"],
            cwd=workspace, text=True, capture_output=True, timeout=60, env=env,
        )
        return diff.stdout if diff.returncode == 0 else "# Patch unavailable: " + redact(diff.stdout + diff.stderr)
    finally:
        index_path.unlink(missing_ok=True)


def write_worktree_patch(workspace: Path, paths: list[str], target: Path) -> None:
    """Persist the exact selected working-tree diff for later diagnosis."""
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(workspace_patch_text(workspace, paths), encoding="utf-8")


def render_protocol(events_path: Path, protocol_path: Path) -> None:
    """Render the redacted JSONL event stream into the human-readable protocol used in the UI/console."""
    lines: list[str] = []
    if events_path.exists():
        for raw in events_path.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                event = json.loads(raw)
                kind = str(event.get("kind", "event")).upper()
                message = redact(str(event.get("message", "")))
                lines.append(f"[{kind}] {message}")
            except Exception:
                lines.append("[EVENT] " + redact(raw))
    protocol_path.parent.mkdir(parents=True, exist_ok=True)
    protocol_path.write_text("\n".join(lines) + ("\n" if lines else ""), encoding="utf-8")


def publish_run_artifacts(
    repo: str,
    base_branch: str,
    job_id: str,
    code_branch: str,
    task: str,
    job_dir: Path,
    workspace: Path,
    files_changed: list[str],
    push: bool,
    logger: EventLogger,
) -> dict[str, Any]:
    """Publish diagnostics on a separate ``agent-runs/<job>`` branch.

    The diagnostics branch is intentionally separate from the code branch so run
    logs never pollute a later merge.  It is published on both success and
    failure when ``--push`` is enabled.
    """
    protocol_path = job_dir / "protocol.log"
    render_protocol(job_dir / "events.jsonl", protocol_path)
    patch_path = job_dir / "working-tree.patch"
    if not patch_path.exists():
        write_worktree_patch(workspace, files_changed, patch_path)
    metadata = {
        "version": VERSION,
        "job_id": job_id,
        "code_branch": code_branch,
        "base_branch": base_branch,
        "published_at": utc_now(),
        "task": redact(task),
        "files_changed": sorted(files_changed),
    }
    (job_dir / "metadata.json").write_text(json.dumps(metadata, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    if not push:
        return {"published": False, "branch": None, "reason": "--push nicht gesetzt"}

    artifact_branch = f"agent-runs/{slugify(job_id, 80)}"
    with tempfile.TemporaryDirectory(prefix="hermclaw-run-artifacts-") as td:
        clone = Path(td) / "repo"
        proc = subprocess.run(
            ["git", "clone", "--no-tags", repo, str(clone)], text=True, capture_output=True, timeout=180
        )
        if proc.returncode != 0:
            raise AgentError("Diagnose-Repository konnte nicht geklont werden:\n" + truncate(proc.stdout + proc.stderr, 3000))
        run_git(["fetch", "--prune", "origin"], cwd=clone)
        remote_artifact = run_git(
            ["ls-remote", "--heads", "origin", f"refs/heads/{artifact_branch}"],
            cwd=clone,
            check=False,
        ).stdout.strip()
        if remote_artifact:
            run_git(["fetch", "origin", artifact_branch], cwd=clone)
            run_git(["switch", "-C", artifact_branch, "FETCH_HEAD"], cwd=clone)
        else:
            base_ref = f"origin/{base_branch}"
            base_check = run_git(["rev-parse", "--verify", base_ref], cwd=clone, check=False)
            if base_check.returncode != 0:
                run_git(["fetch", "origin", f"{base_branch}:refs/remotes/origin/{base_branch}"], cwd=clone)
            run_git(["switch", "-c", artifact_branch, base_ref], cwd=clone)
        run_git(["config", "user.name", os.environ.get("HERMCLAW_GIT_NAME", "Hermclaw Agent")], cwd=clone)
        run_git(["config", "user.email", os.environ.get("HERMCLAW_GIT_EMAIL", "hermclaw-agent@local")], cwd=clone)
        dest = clone / ".hermclaw" / "runs" / slugify(job_id, 80)
        dest.mkdir(parents=True, exist_ok=True)
        for name in ("protocol.log", "events.jsonl", "sources.json", "result.json", "metadata.json", "working-tree.patch"):
            src = job_dir / name
            if src.exists():
                (dest / name).write_bytes(src.read_bytes())
        (dest / "README.txt").write_text(
            "Hermclaw run diagnostics. Dieser Branch dient nur der Diagnose und soll nicht in den Code-Branch gemergt werden.\n"
            "Der vollständige Modell-Transcript (transcript.jsonl) wird absichtlich nicht auf Git veröffentlicht.\n",
            encoding="utf-8",
        )
        # protocol.log is intentionally published even though the project-wide
        # .gitignore ignores *.log. Diagnostics live only on this separate branch.
        run_git(["add", "-f", "-A", "--", ".hermclaw/runs"], cwd=clone)
        staged = run_git(["diff", "--cached", "--name-only", "--"], cwd=clone).stdout.strip()
        if not staged:
            logger.emit("git", f"Run-Protokoll unverändert: {artifact_branch}", branch=artifact_branch)
            commit = run_git(["rev-parse", "HEAD"], cwd=clone).stdout.strip()
            return {"published": True, "branch": artifact_branch, "commit": commit, "unchanged": True}
        run_git(["commit", "-m", f"Hermclaw run protocol: {job_id}"], cwd=clone)
        commit = run_git(["rev-parse", "HEAD"], cwd=clone).stdout.strip()
        run_git(["push", "-u", "origin", artifact_branch], cwd=clone, timeout=180)
    logger.emit("git", f"Run-Protokoll zu GitLab gepusht: {artifact_branch}", branch=artifact_branch, commit=commit)
    return {"published": True, "branch": artifact_branch, "commit": commit}


def _selected_git_paths(workspace: Path, paths: list[str]) -> list[str]:
    """Keep existing paths plus tracked deletions; drop create-then-revert history paths."""
    selected = sorted({str(path).strip().replace("\\", "/") for path in paths if str(path).strip()})
    if not selected:
        return []

    kept = {
        rel for rel in selected
        if (workspace / rel).exists() or (workspace / rel).is_symlink()
    }
    missing = [rel for rel in selected if rel not in kept]
    if missing:
        tracked = subprocess.run(
            ["git", "ls-tree", "-r", "--name-only", "HEAD", "--", *missing],
            cwd=workspace,
            text=True,
            capture_output=True,
            timeout=30,
        )
        if tracked.returncode == 0:
            kept.update(line.strip() for line in tracked.stdout.splitlines() if line.strip())
    return sorted(kept)


def check_workspace_diff(workspace: Path, paths: list[str] | None = None) -> tuple[bool, str]:
    """Run git's whitespace/patch validation against *all* working-tree changes.

    Plain ``git diff --check`` ignores untracked files. That let V8 pass the
    controller gate and fail only after ``git add -A`` in finalization. Use a
    temporary index built from HEAD, add the working tree there, and run the
    exact staged check without touching the real index.
    """
    fd, index_name = tempfile.mkstemp(prefix="hermclaw-index-")
    os.close(fd)
    index_path = Path(index_name)
    try:
        # Git expects either a valid index or a path that does not exist.
        index_path.unlink(missing_ok=True)
        env = {**os.environ, "GIT_INDEX_FILE": str(index_path)}
        read_tree = subprocess.run(
            ["git", "read-tree", "HEAD"], cwd=workspace, text=True, capture_output=True, timeout=30, env=env
        )
        if read_tree.returncode != 0:
            return False, read_tree.stdout + read_tree.stderr
        if paths is None:
            add_args = ["git", "add", "-A", "--", "."]
        else:
            selected = _selected_git_paths(workspace, paths)
            add_args = ["git", "add", "-A", "--", *selected] if selected else None
        if add_args is not None:
            add = subprocess.run(
                add_args, cwd=workspace, text=True, capture_output=True, timeout=60, env=env
            )
            if add.returncode != 0:
                return False, add.stdout + add.stderr
        check = subprocess.run(
            ["git", "diff", "--cached", "--check", "--"],
            cwd=workspace,
            text=True,
            capture_output=True,
            timeout=30,
            env=env,
        )
        return check.returncode == 0, check.stdout + check.stderr
    finally:
        index_path.unlink(missing_ok=True)


def run_git(args: list[str], cwd: Path, timeout: int = 120, check: bool = True) -> subprocess.CompletedProcess[str]:
    proc = subprocess.run(["git", *args], cwd=cwd, text=True, capture_output=True, timeout=timeout)
    if check and proc.returncode != 0:
        raise AgentError(f"git {' '.join(args)} fehlgeschlagen:\n{truncate(proc.stdout + proc.stderr, 5000)}")
    return proc


def slugify(text: str, max_len: int = 42) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return (s[:max_len].rstrip("-") or "task")


def prepare_workspace(repo: str, base_branch: str, workspace_root: Path, job_id: str, task: str, logger: EventLogger) -> tuple[Path, str]:
    workspace_root.mkdir(parents=True, exist_ok=True)
    workspace = (workspace_root / f"job-{job_id}").resolve()
    branch = f"ai/job-{job_id}-{slugify(task)}"
    if workspace.exists():
        raise AgentError(f"Workspace existiert bereits: {workspace}")
    logger.emit("git", "Repository wird in isolierten Workspace geklont.", repo=repo)
    subprocess.run(["git", "clone", "--no-tags", repo, str(workspace)], text=True, capture_output=True, timeout=180, check=True)
    run_git(["fetch", "origin", base_branch], cwd=workspace)
    run_git(["switch", "-c", branch, f"origin/{base_branch}"], cwd=workspace)
    run_git(["config", "user.name", os.environ.get("HERMCLAW_GIT_NAME", "Hermclaw Agent")], cwd=workspace)
    run_git(["config", "user.email", os.environ.get("HERMCLAW_GIT_EMAIL", "hermclaw-agent@local")], cwd=workspace)
    logger.emit("git", f"Arbeitsbranch erstellt: {branch}", branch=branch)
    return workspace, branch


def finalize_git(
    workspace: Path,
    branch: str,
    commit_message: str,
    push: bool,
    logger: EventLogger,
    files_changed: list[str] | None = None,
) -> dict[str, Any]:
    # Only stage paths the agent/runtime recorded as mutations. This prevents
    # unrelated checkout noise (for example CRLF-only gradlew.bat changes) from
    # leaking into an autonomous commit. Keep the legacy all-files behavior
    # only when callers do not provide a path list.
    if files_changed is not None:
        paths = _selected_git_paths(workspace, files_changed)
        if not paths:
            logger.emit("git", "Keine vom Agenten geänderten Dateien vorhanden; kein Commit nötig.")
            return {"committed": False, "pushed": False, "branch": branch, "commit": None}
        run_git(["add", "-A", "--", *paths], cwd=workspace)
        staged = run_git(["diff", "--cached", "--name-only", "--"], cwd=workspace).stdout
        if not staged.strip():
            logger.emit("git", "Keine commitfähigen Agentenänderungen vorhanden; kein Commit nötig.")
            return {"committed": False, "pushed": False, "branch": branch, "commit": None}
    else:
        status = run_git(["status", "--porcelain"], cwd=workspace).stdout
        if not status.strip():
            logger.emit("git", "Keine Git-Änderungen vorhanden; kein Commit nötig.")
            return {"committed": False, "pushed": False, "branch": branch, "commit": None}
        run_git(["add", "-A"], cwd=workspace)

    check = run_git(["diff", "--cached", "--check"], cwd=workspace, check=False)
    if check.returncode != 0:
        raise AgentError("Staged diff enthält Whitespace-/Patchfehler:\n" + truncate(check.stdout + check.stderr, 4000))
    run_git(["commit", "-m", commit_message or "Hermclaw agent changes"], cwd=workspace)
    commit = run_git(["rev-parse", "HEAD"], cwd=workspace).stdout.strip()
    logger.emit("git", f"Commit erstellt: {commit[:12]}", commit=commit)
    pushed = False
    if push:
        run_git(["push", "-u", "origin", branch], cwd=workspace, timeout=180)
        pushed = True
        logger.emit("git", f"Branch zu GitLab gepusht: {branch}", branch=branch)
    return {"committed": True, "pushed": pushed, "branch": branch, "commit": commit}


def build_result(job_dir: Path, agent_result: dict[str, Any], git_result: dict[str, Any]) -> Path:
    result = {
        "version": VERSION,
        "completed_at": utc_now(),
        "agent": agent_result,
        "git": git_result,
    }
    path = job_dir / "result.json"
    path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return path


def cmd_run(ns: argparse.Namespace) -> int:
    job_id = ns.job_id or dt.datetime.now().strftime("%Y%m%d%H%M%S")
    job_meta = Path(ns.runtime_dir).expanduser().resolve() / "agent-jobs" / f"job-{job_id}"
    logger = EventLogger(job_meta / "events.jsonl", quiet=ns.quiet)
    sources = SourceRegistry(job_meta / "sources.json")
    workspace: Path | None = None
    branch = ""
    state: RuntimeState | None = None
    exit_code = 0
    try:
        workspace, branch = prepare_workspace(ns.repo, ns.base, Path(ns.workspace_root).expanduser(), job_id, ns.task, logger)
        state = RuntimeState(task=ns.task, job_id=job_id, workspace=workspace, branch=branch)
        client = LiteLLMClient(ns.litellm_url, ns.model, timeout=ns.llm_timeout, max_output_tokens=ns.max_output_tokens)
        reviewer_client = None
        if not ns.no_independent_review:
            reviewer_client = LiteLLMClient(
                ns.litellm_url,
                ns.review_model or ns.model,
                timeout=ns.llm_timeout,
                max_output_tokens=REVIEW_MAX_OUTPUT_TOKENS,
            )
        controller = AgentController(
            client,
            state,
            logger,
            sources,
            max_turns=ns.max_turns,
            context_tokens=ns.context_tokens,
            max_output_tokens=ns.max_output_tokens,
            transcript_path=job_meta / "transcript.jsonl",
            reviewer_client=reviewer_client,
            max_review_cycles=ns.max_review_cycles,
        )
        agent_result = controller.run()
        # Capture the actual implementation before finalize_git makes the
        # workspace clean. This keeps successful-run diagnostics useful.
        write_worktree_patch(workspace, agent_result.get("files_changed", []), job_meta / "working-tree.patch")
        git_result = finalize_git(workspace, branch, agent_result["commit_message"], ns.push, logger, agent_result.get("files_changed", []))
        result_path = build_result(job_meta, agent_result, git_result)
        logger.emit("done", "Auftrag abgeschlossen.", result=str(result_path), branch=branch)
        print(json.dumps({"ok": True, "job_id": job_id, "branch": branch, "result": str(result_path)}, ensure_ascii=False))
    except subprocess.CalledProcessError as exc:
        exit_code = 2
        logger.emit("error", f"Subprozess fehlgeschlagen: {redact(str(exc))}")
        failure = {
            "version": VERSION,
            "completed_at": utc_now(),
            "ok": False,
            "job_id": job_id,
            "branch": branch or None,
            "error_type": type(exc).__name__,
            "error": redact(str(exc)),
        }
        job_meta.mkdir(parents=True, exist_ok=True)
        (job_meta / "result.json").write_text(json.dumps(failure, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    except Exception as exc:
        exit_code = 1
        logger.emit("error", f"Auftrag fehlgeschlagen: {type(exc).__name__}: {redact(str(exc))}")
        failure = {
            "version": VERSION,
            "completed_at": utc_now(),
            "ok": False,
            "job_id": job_id,
            "branch": branch or None,
            "error_type": type(exc).__name__,
            "error": redact(str(exc)),
        }
        job_meta.mkdir(parents=True, exist_ok=True)
        (job_meta / "result.json").write_text(json.dumps(failure, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    finally:
        if workspace is not None and branch:
            try:
                files_changed = sorted(state.files_changed) if state is not None else []
                patch_path = job_meta / "working-tree.patch"
                if not patch_path.exists():
                    write_worktree_patch(workspace, files_changed, patch_path)
                publish_run_artifacts(
                    ns.repo,
                    ns.base,
                    job_id,
                    branch,
                    ns.task,
                    job_meta,
                    workspace,
                    files_changed,
                    ns.push,
                    logger,
                )
            except Exception as exc:
                # Diagnostics must never hide the real job result.
                logger.emit("warning", f"Run-Protokoll konnte nicht zu GitLab gepusht werden: {type(exc).__name__}: {redact(str(exc))}")
    return exit_code


def cmd_preflight(ns: argparse.Namespace) -> int:
    checks: list[tuple[str, bool, str]] = []
    for binary in ("git", "bash", "python3"):
        proc = subprocess.run(["bash", "-lc", f"command -v {shlex.quote(binary)}"], text=True, capture_output=True)
        checks.append((binary, proc.returncode == 0, proc.stdout.strip() or proc.stderr.strip()))
    try:
        req = urllib.request.Request(ns.litellm_url.replace("/v1/chat/completions", "/v1/models"), method="GET")
        with urllib.request.urlopen(req, timeout=5) as resp:
            checks.append(("LiteLLM", 200 <= resp.status < 500, f"HTTP {resp.status}"))
    except Exception as exc:
        checks.append(("LiteLLM", False, str(exc)))
    if ns.repo:
        proc = subprocess.run(["git", "ls-remote", ns.repo, ns.base], text=True, capture_output=True, timeout=30)
        checks.append(("Git remote", proc.returncode == 0, redact(proc.stdout.strip() or proc.stderr.strip())))
    ok = True
    for name, passed, info in checks:
        print(f"{'OK' if passed else 'FAIL'}  {name}: {info}")
        ok = ok and passed
    return 0 if ok else 1


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description=f"Hermclaw Agent Core V{VERSION} - autonomous local coding loop")
    p.add_argument("--version", action="version", version=VERSION)
    sub = p.add_subparsers(dest="cmd", required=True)

    r = sub.add_parser("run", help="Run one autonomous coding job")
    r.add_argument("--task", required=True)
    r.add_argument("--repo", required=True)
    r.add_argument("--base", default="main")
    r.add_argument("--job-id", default="")
    r.add_argument("--model", default=DEFAULT_MODEL)
    r.add_argument("--litellm-url", default=DEFAULT_LITELLM_URL)
    r.add_argument("--workspace-root", default=str(DEFAULT_WORKSPACE_ROOT))
    r.add_argument("--runtime-dir", default="/home/kiworker/noob2claw_runtime")
    r.add_argument("--max-turns", type=int, default=60)
    r.add_argument(
        "--context-tokens",
        type=int,
        default=DEFAULT_CONTEXT_TOKENS,
        help="num_ctx des gewählten LiteLLM-Alias (local-coder: 16384, local-coder-32k: 32768, local-coder-48k: 49152)",
    )
    r.add_argument("--max-output-tokens", type=int, default=DEFAULT_MAX_OUTPUT_TOKENS)
    r.add_argument("--llm-timeout", type=int, default=1800)
    r.add_argument(
        "--review-model",
        default=os.environ.get("HERMCLAW_REVIEW_MODEL", ""),
        help="Frischer Reviewer-Kontext; leer = dasselbe Modell wie --model.",
    )
    r.add_argument("--max-review-cycles", type=int, default=DEFAULT_MAX_REVIEW_CYCLES)
    r.add_argument("--no-independent-review", action="store_true")
    r.add_argument("--push", action="store_true")
    r.add_argument("--quiet", action="store_true")
    r.set_defaults(func=cmd_run)

    q = sub.add_parser("preflight", help="Check local dependencies, LiteLLM and optional Git remote")
    q.add_argument("--repo", default="")
    q.add_argument("--base", default="main")
    q.add_argument("--litellm-url", default=DEFAULT_LITELLM_URL)
    q.set_defaults(func=cmd_preflight)
    return p


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    ns = parser.parse_args(argv)
    return int(ns.func(ns))


if __name__ == "__main__":
    raise SystemExit(main())
